INSERT INTO `instructors` (`id`, `instructor_name`, `instructor_name_ja`, `instructor_slug`, `instructor_pic`, `instructor_designation`, `instructor_designation_ja`, `instructor_desc`, `instructor_desc_ja`, `status`) VALUES
(1, 'Takeshi Yamamoto', '山本武', 'takeshi-yamamoto', 'Takeshi.png', 'Quantitative & High-Frequency Trading (HFT)', '定量的＆高頻度取引（HFT）', 'A former quant at Nomura Securities, Takeshi now teaches retail traders how to compete with institutional algorithms. His courses (The HFT Survival Guide, Quantitative Trading for Retail Traders) break down complex strategies into actionable systems. Known for his data-driven approach, he specializes in arbitrage, dark pool liquidity, and execution tactics.', '野村證券の元クォントである武氏は、現在、小売業者に機関投資家のアルゴリズムと競合する方法を教えています。 彼のコース（Hftサバイバルガイド、小売トレーダーのための定量的取引）は、複雑な戦略を実用的なシステムに分解します。 データドリブンなアプローチで知られ、アービトラージ、ダークプールの流動性、および実行戦術を専門としています。', 'A'),
(2, 'Naomi Wong', 'ナオミ-ウォン', 'naomi-wong', 'Naomi.png', 'Swing Trading & Smart Money Concepts', 'スイングトレード＆スマートマネーの概念', 'A Hong Kong-based hedge fund analyst turned educator, Naomi specializes in Wyckoff methods and order flow trading. Her course (Swing Trading the Smart Money Way) reveals how institutions manipulate price action—essential knowledge for traders in Asia’s volatile markets. She’s fluent in Cantonese, Mandarin, and English.', '香港を拠点とするヘッジファンドのアナリストは、教育者になって、ナオミはウィッコフメソッドと注文フロー取引を専門としています。 彼女のコース（Swing Trading The Smart Money Way）は、機関がどのように価格行動を操作するかを明らかにしています。 彼女は広東語、北京語、英語に堪能です。', 'A'),
(3, 'Riku Sato', '佐藤陸', 'riku-sato', 'Riku.png', ' Crypto & NFT Trading Strategies', '暗号＆NFT取引戦略', 'A crypto OTC desk veteran from Tokyo, Riku tracks whale movements and exposes wash trading in NFTs. His courses (Crypto Whale Tracking, NFT Flipping Secrets) are packed with real-world case studies from Binance, Bybit, and Japanese exchanges. He’s known for his aggressive but calculated trading style.\r\n\n', '「東京出身のcrypto OTCデスクのベテランであるRikuは、クジラの動きを追跡し、Nftでのウォッシュ取引を公開しています。 彼のコース（CryptoWhale Tracking、NFT Flipping Secrets）には、Binance、bit、および日本の取引所からの実世界のケーススタディが満載されています。 彼は積極的だが計算された取引スタイルで知られています。', 'A'),
(4, 'Hana Lee', 'ハナ-リー', 'hana-lee', 'HanaLee.png', 'Options Flow & Dark Pool Trading', 'オプションフロー＆ダークプール取引', 'Formerly an options market maker in Hong Kong, Hana now teaches traders how to decode institutional order flow. Her courses (Advanced Options Flow Trading, Dark Pool Trading Strategies) reveal how hedge funds hide their moves. She combines technical analysis with deep liquidity insights.', '以前は香港のオプションマーケットメーカーでしたが、Hanaは現在、機関投資家の注文フローを解読する方法をトレーダーに教えています。 彼女のコース（高度なオプションフロー取引、ダークプール取引戦略）は、ヘッジファンドが彼らの動きを隠す方法を明らかにします。 彼女はテクニカル分析と深い流動性の洞察を組み合わせています。', 'A'),
(5, 'Kenjiro Matsuda', '松田健次郎', 'kenjiro-matsuda', 'Kenjiro.png', 'Risk Management & Trading Psychology', 'リスクマネジメント＆トレーディング心理学', 'An ex-pro poker player and derivatives trader, Kenjiro applies game theory to trading. His courses (The Kelly Criterion & Bet Sizing, Trading Like a Poker Pro) focus on position sizing, emotional discipline, and post-trade analysis—critical for surviving Asia’s high-leverage markets.', '元プロのポーカープレーヤーであり、デリバティブトレーダーであるKenjiroは、ゲーム理論を取引に適用します。 彼のコース(The Kelly Criterion&Bet Sizing,Trading Like A Poker Pro)は、ポジションのサイジング、感情的な規律、取引後の分析に焦点を当てており、アジアの高レバレッジ市場を存続させるために重要です。', 'A'),
(6, 'Ling Zhao', '陵趙', 'ling-zhao', 'Ling.png', 'Behavioral Finance & Contrarian Trading', '行動ファイナンス＆逆張り取引', 'A behavioral economist with a background in Hong Kong’s hedge fund scene, Ling teaches traders how to exploit cognitive biases. Her courses (Sentiment & Contrarian Trading, Crafting Your Trading Edge) are especially useful in Japan’s herd-driven retail markets and Hong Kong’s speculative frenzy.', '香港のヘッジファンド業界のバックグラウンドを持つ行動経済学者であるLingは、トレーダーに認知バイアスを悪用する方法を教えています。 彼女のコース（センチメント＆逆張りの取引、あなたの取引エッジを作り上げる）は、日本の群れ主導の小売市場と香港の投機的な狂乱で特に役立ちます。', 'A');
