INSERT INTO `products` (`id`, `title`, `title_jp`, `slug`, `summary`, `summary_jp`, `description`, `description_jp`, `meta_title`, `meta_description`, `meta_keyword`, `photo`, `stock`, `size`, `condition`, `status`, `price`, `price_in_points`, `price_jp`, `price_hk`, `discount`, `is_featured`, `extra_description`, `extra_description_jp`, `cat_id`, `child_cat_id`, `brand_id`, `duration`, `skill_level`, `skill_level_jp`, `lectures`, `language`, `language_jp`, `genres`, `created_at`, `updated_at`) VALUES
(1, 'Beginner Weight Training', '初心者向けウエイトトレーニング', 'beginner-weight-training', 'Build a strong foundation in weight training by learning proper lifting techniques, resistance exercises, workout planning, and gym safety. Develop confidence while improving strength, muscular endurance, coordination, and overall fitness through structured beginner friendly training sessions.', '正しいリフティング技術、レジスタンストレーニング、ワークアウト計画、ジムでの安全対策を学びながら、ウエイトトレーニングの基礎を築きます。初心者向けの体系的なトレーニングを通じて、自信を身につけ、筋力、筋持久力、協調性、総合的なフィットネスを向上させます。', 'Build a solid foundation in weight training by understanding proper exercise techniques, equipment usage, workout programming, and recovery methods. Learn how resistance training improves muscular strength, endurance, posture, and overall physical performance while developing safe lifting habits that reduce injury risk. Explore progressive overload, exercise selection, warm up routines, and beginner focused workout structures designed to help you achieve long term fitness goals with confidence and consistency.', '正しいエクササイズ技術、器具の使用方法、ワークアウトプログラム、回復方法を学び、ウエイトトレーニングの確かな基礎を築きます。レジスタンストレーニングが筋力、筋持久力、姿勢、身体能力をどのように向上させるかを理解し、安全なリフティング習慣を身につけて怪我のリスクを軽減します。段階的負荷、種目選択、ウォームアップ、初心者向けトレーニング構成を学び、長期的なフィットネス目標を継続的に達成するための実践的な知識を身につけます。', 'Beginner Weight Training', 'Learn beginner weight training techniques, resistance exercises, workout planning, and safe lifting practices to build strength, improve fitness, and develop healthy training habits.', 'beginner weight training, strength training, resistance training, gym workout, weight lifting, fitness basics, muscle strength', 'storage/photos/products/1.webp', 999999, NULL, NULL, 'active', 32.00, 32, 32.00, 32.00, 0.00, 1, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(2, 'Muscle Building Fundamentals', '筋肉増強の基礎', 'muscle-building-fundamentals', 'Learn the essential principles of muscle building through effective resistance training, progressive overload, recovery strategies, and proper exercise selection. Develop the knowledge and practical skills needed to increase muscle mass, improve strength, and build a balanced physique safely and efficiently.', '効果的なレジスタンストレーニング、漸進的過負荷、回復戦略、適切な種目選択を通じて、筋肉増強の基本原則を学びます。筋肉量を増やし、筋力を向上させ、バランスの取れた身体を安全かつ効率的に作るために必要な知識と実践的なスキルを身につけます。', 'Develop a strong understanding of the science behind muscle growth by exploring resistance training techniques, progressive overload, training intensity, exercise programming, recovery methods, and consistency. Learn how muscles adapt to training, how to structure effective workout plans, and how proper nutrition and recovery contribute to long term muscle development. Gain practical knowledge that helps improve muscular size, strength, and overall physical performance while establishing sustainable training habits.', 'レジスタンストレーニングの技術、漸進的過負荷、トレーニング強度、ワークアウトプログラム、回復方法、継続性を学びながら、筋肉成長の科学的な仕組みを理解します。筋肉がトレーニングにどのように適応するか、効果的なトレーニングプランの作り方、適切な栄養と回復が長期的な筋肉の発達にどのように貢献するかを学びます。筋肉量、筋力、身体能力を向上させるための実践的な知識を身につけ、持続可能なトレーニング習慣を確立します。', 'Muscle Building Fundamentals', 'Master the fundamentals of muscle building through resistance training, progressive overload, effective workout planning, recovery, and proven muscle growth principles.', 'muscle building, hypertrophy, resistance training, muscle growth, workout planning, strength training, fitness', 'storage/photos/products/2.webp', 999999, NULL, NULL, 'active', 40.00, 40, 40.00, 40.00, 0.00, 1, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(3, 'Powerlifting Essentials', 'パワーリフティングの基礎', 'powerlifting-essentials', 'Learn the core principles of powerlifting by mastering the squat, bench press, and deadlift. Develop proper lifting techniques, strength programming, recovery methods, and performance strategies that improve maximum strength while promoting safe and effective training practices.', 'スクワット、ベンチプレス、デッドリフトを習得しながら、パワーリフティングの基本原則を学びます。正しいリフティング技術、筋力向上プログラム、回復方法、パフォーマンス向上戦略を身につけ、安全で効果的なトレーニングを通じて最大筋力を高めます。', 'Build a comprehensive understanding of powerlifting through detailed instruction on the three primary competition lifts, training periodisation, exercise technique, progressive overload, mobility, and recovery. Learn how to improve lifting efficiency, increase overall strength, reduce injury risk, and create structured strength training programs that support long term athletic development. Develop practical skills that enhance confidence, performance, and consistency in powerlifting and strength focused training.', 'スクワット、ベンチプレス、デッドリフトの三大種目、トレーニングのピリオダイゼーション、正しいフォーム、漸進的過負荷、モビリティ、回復方法について詳しく学び、パワーリフティングを総合的に理解します。リフティング効率を高め、全身の筋力を向上させ、怪我のリスクを軽減し、長期的な競技力向上につながる体系的な筋力トレーニングプログラムを作成する方法を習得します。実践的なスキルを身につけることで、パワーリフティングと筋力トレーニングにおける自信、パフォーマンス、継続性を向上させます。', 'Powerlifting Essentials', 'Learn powerlifting fundamentals including squat, bench press, deadlift, strength programming, lifting technique, and performance improvement strategies.', 'powerlifting, squat, bench press, deadlift, strength training, powerlifting fundamentals, lifting technique', 'storage/photos/products/3.webp', 999999, NULL, NULL, 'active', 35.00, 35, 35.00, 35.00, 0.00, 1, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(4, 'Functional Strength Training', '機能的筋力トレーニング', 'functional-strength-training', 'Develop practical strength through functional training exercises that improve balance, mobility, coordination, stability, and overall athletic performance. Learn movement patterns and training techniques that enhance everyday activities while reducing injury risk and supporting long term physical health.', 'バランス、可動性、協調性、安定性、総合的な運動能力を向上させる機能的トレーニングを通じて、実践的な筋力を身につけます。日常生活の動作を改善し、怪我のリスクを軽減しながら、長期的な健康を支える動作パターンとトレーニング技術を学びます。', 'Gain a comprehensive understanding of functional strength training by learning exercises that replicate natural human movement and improve real world physical performance. Explore bodyweight exercises, resistance training, core stability, balance development, mobility improvement, movement efficiency, and injury prevention strategies. Develop practical fitness skills that strengthen the entire body, improve posture, enhance coordination, and support better performance in sports, work, and everyday life through structured functional training programs.', '自然な身体の動きを再現するエクササイズを学び、実生活で役立つ身体能力を向上させることで、機能的筋力トレーニングを総合的に理解します。自重トレーニング、レジスタンストレーニング、体幹の安定性、バランス能力、柔軟性向上、効率的な動作、怪我予防について学びます。全身の筋力を強化し、姿勢を改善し、協調性を高め、スポーツや仕事、日常生活でのパフォーマンス向上につながる実践的なフィットネススキルを体系的な機能的トレーニングを通じて習得します。', 'Functional Strength Training', 'Learn functional strength training techniques that improve balance, mobility, coordination, stability, movement efficiency, and overall physical performance.', 'functional strength training, functional fitness, mobility, core stability, movement training, athletic performance, strength exercises', 'storage/photos/products/4.webp', 999999, NULL, NULL, 'active', 33.00, 33, 33.00, 33.00, 0.00, 1, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(5, 'Advanced Hypertrophy Program', '高度な筋肥大プログラム', 'advanced-hypertrophy-program', 'Master advanced hypertrophy training techniques designed to maximize muscle growth through strategic workout programming, progressive overload, training intensity, recovery optimization, and exercise variation. Build a stronger, more muscular physique using evidence based training principles.', '戦略的なトレーニングプログラム、漸進的過負荷、トレーニング強度、回復の最適化、種目のバリエーションを活用し、筋肥大を最大化する高度なトレーニング技術を学びます。科学的根拠に基づいたトレーニング原則を用いて、より大きく力強い身体を作り上げます。', 'Develop advanced knowledge of hypertrophy focused resistance training by exploring muscle growth science, advanced workout programming, training volume, exercise selection, recovery management, and progressive overload techniques. Learn how to optimize every stage of muscle development while improving strength, muscular symmetry, and overall physique. Gain practical experience creating structured hypertrophy programs that deliver sustainable results and support long term fitness performance through intelligent training strategies.', '筋肥大に特化したレジスタンストレーニングについて、筋肉成長の科学、上級者向けトレーニングプログラム、トレーニングボリューム、種目選択、回復管理、漸進的過負荷の技術を学びながら高度な知識を身につけます。筋肉の発達を最適化し、筋力、身体のバランス、全体的な体格を向上させる方法を理解します。実践的なプログラム作成スキルを習得し、長期的な成果を生み出す効率的な筋肥大プログラムを設計できるようになります。', 'Advanced Hypertrophy Program', 'Master advanced hypertrophy training methods, workout programming, progressive overload, recovery strategies, and muscle growth techniques to maximize lean muscle development.', 'advanced hypertrophy, muscle hypertrophy, muscle growth, bodybuilding, resistance training, workout programming, advanced fitness', 'storage/photos/products/5.webp', 999999, NULL, NULL, 'active', 38.00, 38, 38.00, 38.00, 0.00, 1, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(6, 'Fat Loss Blueprint', '脂肪燃焼プログラム', 'fat-loss-blueprint', 'Build a complete understanding of effective fat loss through structured training, proper nutrition, calorie management, and sustainable lifestyle habits. Learn proven strategies that help reduce body fat, preserve lean muscle, improve metabolism, and achieve long term health and fitness goals.', '体系的なトレーニング、適切な栄養管理、カロリーコントロール、持続可能な生活習慣を通じて、効果的な脂肪燃焼の基礎を学びます。体脂肪を減らし、筋肉量を維持し、代謝を高め、長期的な健康とフィットネス目標を達成するための実践的な方法を身につけます。', 'Develop a comprehensive understanding of body fat reduction by exploring calorie balance, nutrition planning, resistance training, cardiovascular exercise, metabolism, recovery, and healthy lifestyle habits. Learn how to create sustainable fat loss programs that support consistent progress without sacrificing muscle mass or overall health. Gain practical knowledge that helps improve body composition, increase energy levels, and establish long term habits for maintaining a healthy and active lifestyle.', 'カロリーバランス、栄養計画、レジスタンストレーニング、有酸素運動、代謝、回復、健康的な生活習慣を学びながら、体脂肪を減らすための総合的な知識を身につけます。筋肉量や健康を損なうことなく継続できる脂肪燃焼プログラムを作成する方法を学びます。体組成を改善し、エネルギーレベルを高め、健康的で活動的な生活を維持するための長期的な習慣を身につける実践的なスキルを習得します。', 'Fat Loss Blueprint', 'Learn effective fat loss strategies through nutrition, calorie management, strength training, cardio, and sustainable lifestyle habits for long term results.', 'fat loss, weight loss, calorie deficit, body fat reduction, fitness nutrition, metabolism, healthy lifestyle', 'storage/photos/products/6.webp', 999999, NULL, NULL, 'active', 36.00, 36, 36.00, 36.00, 0.00, 1, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(7, 'HIIT Training Masterclass', 'HIITトレーニングマスタークラス', 'hiit-training-masterclass', 'Master high intensity interval training through structured workouts designed to improve cardiovascular fitness, burn calories efficiently, increase endurance, and enhance overall athletic performance. Learn safe training methods that deliver maximum results in less time.', '心肺機能を向上させ、効率的にカロリーを消費し、持久力を高め、総合的な運動能力を向上させるために設計された高強度インターバルトレーニングを学びます。短時間で最大の成果を得るための安全で効果的なトレーニング方法を習得します。', 'Gain a comprehensive understanding of high intensity interval training by exploring workout structure, exercise selection, work to rest ratios, cardiovascular conditioning, recovery techniques, and progressive training methods. Learn how HIIT improves endurance, accelerates calorie expenditure, supports fat loss, and enhances athletic performance while reducing overall workout time. Develop practical skills that help create effective HIIT programs suitable for a wide range of fitness levels and training goals.', 'ワークアウト構成、種目選択、運動と休息の比率、心肺機能向上、回復方法、段階的なトレーニング手法を学びながら、高強度インターバルトレーニングを総合的に理解します。HIITが持久力を高め、カロリー消費を促進し、脂肪燃焼をサポートし、短時間で運動能力を向上させる仕組みを学びます。さまざまなフィットネスレベルや目標に対応した効果的なHIITプログラムを作成するための実践的な知識とスキルを習得します。', 'HIIT Training Masterclass', 'Master high intensity interval training through structured HIIT workouts that improve endurance, burn calories, increase fitness, and support effective fat loss.', 'hiit training, high intensity interval training, cardio workout, fat burning, endurance training, interval workouts, fitness training', 'storage/photos/products/7.webp', 999999, NULL, NULL, 'active', 38.00, 38, 38.00, 38.00, 0.00, 1, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(8, 'Cardio for Weight Loss', '減量のための有酸素運動', 'cardio-for-weight-loss', 'Learn how cardiovascular exercise supports effective weight loss through structured training programs, calorie expenditure, endurance development, and heart health improvement. Discover practical cardio techniques that help reduce body fat while improving overall fitness and long term wellness.', '体系的なトレーニングプログラム、カロリー消費、持久力向上、心臓の健康改善を通じて、有酸素運動が効果的な減量にどのように役立つかを学びます。体脂肪を減らしながら総合的な体力と長期的な健康を向上させる実践的な有酸素運動のテクニックを身につけます。', 'Develop a comprehensive understanding of cardiovascular training and its role in healthy weight management. Explore different forms of cardio including walking, jogging, cycling, rowing, and interval training while learning how to measure exercise intensity, optimise calorie expenditure, and improve endurance safely. Gain practical knowledge for creating balanced cardio programs that complement strength training, enhance cardiovascular health, support sustainable fat loss, and improve overall physical performance.', '有酸素トレーニングと健康的な体重管理におけるその役割について総合的に学びます。ウォーキング、ジョギング、サイクリング、ローイング、インターバルトレーニングなどさまざまな有酸素運動を学びながら、運動強度の測定方法、カロリー消費の最適化、持久力を安全に向上させる方法を習得します。筋力トレーニングと組み合わせた効果的な有酸素運動プログラムを作成し、心肺機能を高め、持続可能な脂肪燃焼を実現し、総合的な身体能力を向上させる実践的な知識を身につけます。', 'Cardio for Weight Loss', 'Learn effective cardio training methods that support healthy weight loss, improve endurance, increase calorie burning, and strengthen cardiovascular fitness.', 'cardio for weight loss, cardio exercise, fat burning, endurance training, cardiovascular fitness, calorie burning, weight management', 'storage/photos/products/8.webp', 999999, NULL, NULL, 'active', 34.00, 34, 34.00, 34.00, 0.00, 1, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(9, 'Metabolic Conditioning', 'メタボリックコンディショニング', 'metabolic-conditioning', 'Improve endurance, strength, and energy efficiency through metabolic conditioning workouts designed to enhance cardiovascular performance, increase calorie expenditure, and support overall fitness. Learn structured training methods that develop work capacity while promoting sustainable health and athletic performance.', '心肺機能を向上させ、カロリー消費を高め、総合的なフィットネスをサポートするメタボリックコンディショニングを学びます。持久力、筋力、エネルギー効率を高めながら、作業能力を向上させる体系的なトレーニング方法を習得し、健康と運動能力の向上を目指します。', 'Develop a comprehensive understanding of metabolic conditioning by exploring high efficiency training methods that combine strength, endurance, speed, and cardiovascular fitness. Learn how different energy systems function during exercise, how to structure conditioning workouts, manage recovery, improve work capacity, and maximise overall performance. Gain practical knowledge for designing balanced conditioning programs that increase stamina, support fat loss, improve athletic ability, and promote long term physical fitness.', '筋力、持久力、スピード、心肺機能を組み合わせた高効率トレーニングを通じて、メタボリックコンディショニングを総合的に理解します。運動中に働くエネルギーシステムの仕組み、コンディショニングワークアウトの構成方法、回復管理、作業能力の向上、総合的なパフォーマンスの最大化について学びます。持久力を高め、脂肪燃焼を促進し、運動能力を向上させ、長期的な健康を支えるバランスの取れたコンディショニングプログラムを設計するための実践的な知識を身につけます。', 'Metabolic Conditioning', 'Learn metabolic conditioning techniques that improve endurance, work capacity, cardiovascular fitness, calorie expenditure, and overall athletic performance.', 'metabolic conditioning, conditioning workout, endurance training, cardiovascular fitness, stamina, athletic performance, calorie burning', 'storage/photos/products/9.webp', 999999, NULL, NULL, 'active', 37.00, 37, 37.00, 37.00, 0.00, 1, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(10, '30 Day Body Transformation', '30日間ボディトランスフォーメーション', '30-day-body-transformation', 'Follow a structured 30 day fitness transformation program that combines strength training, cardiovascular exercise, nutrition planning, recovery, and healthy habits to improve body composition, increase fitness levels, and build sustainable long term results.', '筋力トレーニング、有酸素運動、栄養管理、回復、健康的な生活習慣を組み合わせた30日間の体系的なフィットネスプログラムを通じて、体組成を改善し、体力を向上させ、長期的に維持できる健康的な成果を目指します。', 'Develop the knowledge and discipline required to complete a comprehensive 30 day body transformation program focused on improving strength, endurance, mobility, nutrition, recovery, and lifestyle habits. Learn how to set realistic fitness goals, monitor progress, establish consistent workout routines, and build sustainable healthy behaviours. Gain practical experience following a structured transformation plan that promotes fat loss, lean muscle development, improved physical performance, and long term wellness through balanced fitness and nutrition practices.', '筋力、持久力、柔軟性、栄養管理、回復、生活習慣の改善を中心とした30日間の総合的なボディトランスフォーメーションプログラムを実践するための知識と習慣を身につけます。現実的な目標設定、進捗管理、継続的なトレーニング習慣の構築、健康的な生活習慣の定着方法を学びます。体系的なプログラムを通じて、脂肪燃焼、筋肉の発達、身体能力の向上、そして長期的な健康維持を実現するための実践的なスキルを習得します。', '30 Day Body Transformation', 'Complete a structured 30 day fitness transformation program combining exercise, nutrition, healthy habits, and progress tracking for lasting physical results.', '30 day body transformation, fitness challenge, weight loss program, body transformation, healthy lifestyle, workout plan, fitness goals', 'storage/photos/products/10.webp', 999999, NULL, NULL, 'active', 40.00, 40, 40.00, 40.00, 0.00, 1, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(11, 'Yoga for Beginners', '初心者のためのヨガ', 'yoga-for-beginners', 'Build a strong foundation in yoga by learning essential poses, breathing techniques, body alignment, flexibility exercises, and relaxation practices. Develop confidence through safe and structured sessions that improve physical health, mental wellbeing, balance, and overall fitness.', '基本的なポーズ、呼吸法、正しい姿勢、柔軟性を高めるエクササイズ、リラクゼーションを学びながら、ヨガの基礎を身につけます。安全で体系的なレッスンを通じて、身体の健康、心の健康、バランス感覚、そして総合的なフィットネスを向上させる自信を育みます。', 'Develop a comprehensive understanding of beginner friendly yoga by exploring foundational postures, breathing techniques, stretching exercises, balance training, mindfulness, and relaxation methods. Learn how yoga supports flexibility, strength, posture, stress management, and overall wellbeing while practising safe movement techniques suitable for all fitness levels. Gain practical experience following structured yoga routines that encourage healthy movement, improved mobility, mental clarity, and long term physical wellness.', '初心者向けヨガの基礎を学び、基本ポーズ、呼吸法、ストレッチ、バランストレーニング、マインドフルネス、リラクゼーション方法を総合的に理解します。ヨガが柔軟性、筋力、姿勢、ストレス管理、健康全般にどのように役立つかを学び、安全で無理のない動きを身につけます。体系的なヨガルーティンを実践することで、健康的な身体の動き、可動域の向上、心の落ち着き、そして長期的な健康維持を支える実践的なスキルを習得します。', 'Yoga for Beginners', 'Learn beginner friendly yoga poses, breathing techniques, flexibility exercises, and relaxation practices that improve balance, mobility, and overall wellbeing.', 'yoga for beginners, beginner yoga, yoga poses, flexibility, breathing exercises, mindfulness, wellness', 'storage/photos/products/11.webp', 999999, NULL, NULL, 'active', 31.00, 31, 31.00, 31.00, 0.00, 1, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(12, 'Power Yoga Training', 'パワーヨガトレーニング', 'power-yoga-training', 'Build strength, flexibility, endurance, and balance through dynamic power yoga sessions that combine flowing movements with controlled breathing techniques. Learn structured practices that improve physical fitness, body awareness, and overall wellbeing while enhancing energy and mental focus.', '流れるような動きと呼吸法を組み合わせたダイナミックなパワーヨガを通じて、筋力、柔軟性、持久力、バランスを高めます。身体能力、身体意識、健康全般を向上させながら、エネルギーと集中力を高める体系的なヨガプラクティスを学びます。', 'Develop a comprehensive understanding of power yoga by exploring dynamic yoga sequences, advanced standing poses, core strengthening exercises, flexibility training, controlled breathing, and mindful movement. Learn how power yoga improves muscular endurance, cardiovascular fitness, posture, mobility, and overall body control while promoting mental clarity and stress management. Gain practical experience performing structured routines that build full body strength, increase flexibility, and support long term physical and mental wellness.', 'ダイナミックなヨガシークエンス、高度な立位ポーズ、体幹強化エクササイズ、柔軟性トレーニング、呼吸法、マインドフルな動きを学びながら、パワーヨガを総合的に理解します。パワーヨガが筋持久力、心肺機能、姿勢、可動性、身体のコントロールを向上させるとともに、精神的な集中力とストレス管理にどのように役立つかを学びます。体系的なトレーニングを実践することで、全身の筋力を高め、柔軟性を向上させ、長期的な心身の健康を支える実践的なスキルを習得します。', 'Power Yoga Training', 'Master dynamic power yoga techniques that improve strength, flexibility, endurance, posture, balance, and overall physical and mental wellbeing.', 'power yoga, yoga training, dynamic yoga, strength yoga, flexibility, core strength, mindful movement', 'storage/photos/products/12.webp', 999999, NULL, NULL, 'active', 35.00, 35, 35.00, 35.00, 0.00, 1, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(13, 'Mobility and Flexibility', 'モビリティと柔軟性', 'mobility-and-flexibility', 'Improve joint mobility, muscle flexibility, posture, and movement quality through structured stretching routines and mobility exercises. Learn techniques that reduce stiffness, enhance physical performance, prevent injuries, and support long term health and functional movement.', '体系的なストレッチとモビリティエクササイズを通じて、関節の可動域、筋肉の柔軟性、姿勢、動作の質を向上させます。身体の硬さを軽減し、運動能力を高め、怪我を予防し、長期的な健康と機能的な動きを支えるテクニックを学びます。', 'Develop a comprehensive understanding of mobility and flexibility training by exploring dynamic stretching, static stretching, joint mobility exercises, muscle activation techniques, posture correction, and movement efficiency. Learn how regular mobility practice improves range of motion, reduces injury risk, supports faster recovery, and enhances performance during daily activities and athletic training. Gain practical experience designing balanced mobility routines that promote healthy movement, better body control, and long term physical wellbeing.', 'ダイナミックストレッチ、スタティックストレッチ、関節モビリティエクササイズ、筋肉活性化、姿勢改善、効率的な身体の動きを学びながら、モビリティと柔軟性トレーニングを総合的に理解します。継続的なモビリティトレーニングが可動域を広げ、怪我のリスクを軽減し、回復を促進し、日常生活やスポーツでのパフォーマンスを向上させる方法を学びます。健康的な身体の動き、優れた身体コントロール、長期的な健康維持を支えるバランスの取れたモビリティプログラムを作成する実践的なスキルを習得します。', 'Mobility and Flexibility', 'Improve mobility, flexibility, posture, and joint health through structured stretching routines and movement techniques that enhance performance and prevent injuries.', 'mobility training, flexibility exercises, stretching, joint mobility, posture improvement, injury prevention, movement training', 'storage/photos/products/13.webp', 999999, NULL, NULL, 'active', 34.00, 34, 34.00, 34.00, 0.00, 1, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(14, 'Morning Yoga Routine', '朝のヨガルーティン', 'morning-yoga-routine', 'Start each day with an energising morning yoga routine designed to improve flexibility, mobility, posture, circulation, and mental focus. Learn simple yet effective sequences that awaken the body, reduce stiffness, increase energy, and promote a healthy and balanced lifestyle.', '柔軟性、可動性、姿勢、血行、集中力を高める朝のヨガルーティンを学び、一日を活力に満ちた状態で始めましょう。身体を目覚めさせ、こわばりを和らげ、エネルギーを高め、健康的でバランスの取れた生活を促進するシンプルで効果的なヨガシークエンスを習得します。', 'Develop a comprehensive understanding of morning yoga by exploring gentle stretching, breathing exercises, mobility drills, balance training, mindfulness practices, and energising yoga sequences. Learn how a consistent morning routine improves flexibility, posture, circulation, mental clarity, and overall wellbeing while preparing the body and mind for daily activities. Gain practical experience performing structured yoga sessions that encourage healthy movement, reduce stress, increase productivity, and support long term physical and mental wellness.', '優しいストレッチ、呼吸法、モビリティエクササイズ、バランストレーニング、マインドフルネス、活力を高めるヨガシークエンスを学びながら、朝のヨガを総合的に理解します。毎朝のヨガ習慣が柔軟性、姿勢、血行、集中力、健康全般を向上させ、日常生活に向けて心身を整える方法を学びます。体系的なヨガセッションを実践することで、健康的な身体の動き、ストレス軽減、生産性向上、そして長期的な心身の健康を支える実践的なスキルを身につけます。', 'Morning Yoga Routine', 'Learn energising morning yoga routines that improve flexibility, posture, mobility, focus, circulation, and overall wellbeing while preparing your body for the day.', 'morning yoga, daily yoga routine, yoga exercises, flexibility, mobility, mindfulness, healthy lifestyle', 'storage/photos/products/14.webp', 999999, NULL, NULL, 'active', 32.00, 32, 32.00, 32.00, 0.00, 1, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(15, 'Stress Relief Yoga', 'ストレス解消ヨガ', 'stress-relief-yoga', 'Learn calming yoga practices designed to reduce stress, ease muscle tension, improve breathing, and promote mental and physical relaxation. Develop healthy routines that support emotional wellbeing, mindfulness, better sleep, and long term balance through gentle yoga techniques.', 'ストレスを軽減し、筋肉の緊張を和らげ、呼吸を整え、心身のリラックスを促進する穏やかなヨガを学びます。感情の健康、マインドフルネス、睡眠の質の向上、そして長期的な心身のバランスを支える健康的な習慣を身につけます。', 'Develop a comprehensive understanding of stress relief yoga by exploring gentle yoga postures, breathing exercises, mindfulness practices, meditation techniques, relaxation methods, and restorative movements. Learn how regular yoga practice helps reduce anxiety, improve emotional wellbeing, relieve physical tension, enhance sleep quality, and restore mental balance. Gain practical experience performing structured yoga sessions that encourage relaxation, increase self awareness, improve resilience, and support long term physical and mental wellness.', '穏やかなヨガのポーズ、呼吸法、マインドフルネス、瞑想、リラクゼーション、リストラティブヨガを学びながら、ストレス解消ヨガを総合的に理解します。継続的なヨガの実践が、不安の軽減、心の健康の向上、身体の緊張緩和、睡眠の質の改善、精神的な安定にどのように役立つかを学びます。体系的なヨガセッションを実践することで、深いリラクゼーション、自己理解、精神的な回復力、そして長期的な心身の健康を支える実践的なスキルを習得します。', 'Stress Relief Yoga', 'Practice gentle yoga techniques that reduce stress, improve relaxation, support better sleep, enhance mindfulness, and promote long term mental and physical wellbeing.', 'stress relief yoga, relaxation yoga, mindfulness, meditation, breathing exercises, restorative yoga, mental wellness', 'storage/photos/products/15.webp', 999999, NULL, NULL, 'active', 33.00, 33, 33.00, 33.00, 0.00, 1, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(16, 'Sports Nutrition Basics', 'スポーツ栄養学の基礎', 'sports-nutrition-basics', 'Build a strong foundation in sports nutrition by learning how proper nutrition supports energy production, athletic performance, muscle recovery, hydration, and overall health. Understand the role of balanced eating habits in achieving fitness goals and improving physical performance.', 'スポーツ栄養学の基礎を学び、適切な栄養がエネルギー産生、運動能力、筋肉の回復、水分補給、そして健康全般にどのように役立つかを理解します。バランスの取れた食生活がフィットネス目標の達成や身体能力の向上に果たす役割を学びます。', 'Develop a comprehensive understanding of sports nutrition by exploring the functions of carbohydrates, proteins, healthy fats, vitamins, minerals, hydration, meal timing, and recovery nutrition. Learn how nutritional strategies influence exercise performance, endurance, strength development, muscle recovery, and overall wellbeing. Gain practical knowledge for creating balanced nutrition plans that support training goals, improve athletic performance, promote healthy body composition, and encourage long term healthy eating habits.', '炭水化物、たんぱく質、健康的な脂質、ビタミン、ミネラル、水分補給、食事のタイミング、回復栄養について学びながら、スポーツ栄養学を総合的に理解します。栄養戦略が運動能力、持久力、筋力向上、筋肉の回復、健康全般にどのような影響を与えるかを学びます。トレーニング目標を支え、運動能力を高め、健康的な身体づくりを促進し、長期的な健康的食習慣を身につけるためのバランスの取れた栄養計画を作成する実践的な知識を習得します。', 'Sports Nutrition Basics', 'Learn the fundamentals of sports nutrition including healthy eating, hydration, nutrient balance, recovery nutrition, and meal planning to improve athletic performance.', 'sports nutrition, fitness nutrition, healthy eating, hydration, muscle recovery, athletic performance, nutrition basics', 'storage/photos/products/16.webp', 999999, NULL, NULL, 'active', 35.00, 35, 35.00, 35.00, 0.00, 1, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(17, 'Meal Planning for Fitness', 'フィットネスのための食事計画', 'meal-planning-for-fitness', 'Learn how to create balanced meal plans that support fitness goals through proper nutrition, portion control, nutrient timing, and healthy food choices. Develop practical meal planning skills that improve energy levels, recovery, body composition, and long term health.', '適切な栄養、食事量の管理、栄養摂取のタイミング、健康的な食品選びを通じて、フィットネス目標を支えるバランスの取れた食事計画を作成する方法を学びます。エネルギーレベル、回復力、体組成、そして長期的な健康を向上させる実践的な食事計画スキルを身につけます。', 'Develop a comprehensive understanding of fitness meal planning by exploring calorie requirements, macronutrient balance, portion control, meal preparation, grocery planning, healthy recipes, and nutrient timing. Learn how to organise daily and weekly meal plans that support muscle growth, fat loss, athletic performance, and overall wellbeing. Gain practical experience designing sustainable nutrition strategies that simplify healthy eating, improve consistency, reduce unnecessary food choices, and promote long term fitness success.', 'カロリー必要量、三大栄養素のバランス、食事量の管理、ミールプレップ、買い物計画、健康的なレシピ、栄養摂取のタイミングを学びながら、フィットネス向けの食事計画を総合的に理解します。筋肉の成長、脂肪燃焼、運動能力、健康全般を支える毎日および毎週の食事プランを作成する方法を学びます。健康的な食生活を継続しやすくし、一貫性を高め、無駄な食事選択を減らし、長期的なフィットネス成功を支える持続可能な栄養戦略を設計する実践的なスキルを習得します。', 'Meal Planning for Fitness', 'Learn fitness meal planning, portion control, healthy recipes, nutrient timing, and balanced nutrition strategies that support performance and long term health.', 'meal planning, fitness nutrition, healthy meals, meal prep, portion control, nutrition planning, healthy eating', 'storage/photos/products/17.webp', 999999, NULL, NULL, 'active', 36.00, 36, 36.00, 36.00, 0.00, 1, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(18, 'Protein and Muscle Nutrition', 'たんぱく質と筋肉栄養学', 'protein-and-muscle-nutrition', 'Learn how protein and proper nutrition support muscle growth, recovery, strength development, and overall physical performance. Understand daily protein requirements, food sources, meal timing, and balanced nutrition strategies that help maximize training results and long term health.', 'たんぱく質と適切な栄養が筋肉の成長、回復、筋力向上、そして総合的な運動能力にどのように役立つかを学びます。1日に必要なたんぱく質量、食品の選び方、食事のタイミング、そしてトレーニング効果と長期的な健康を最大限に高めるバランスの取れた栄養戦略を理解します。', 'Develop a comprehensive understanding of protein and muscle nutrition by exploring protein quality, amino acids, digestion, nutrient timing, recovery meals, muscle protein synthesis, and balanced dietary planning. Learn how nutrition influences muscle repair, lean muscle development, exercise recovery, and athletic performance. Gain practical knowledge for creating nutrition plans that provide adequate protein intake, support strength training, improve body composition, and encourage sustainable healthy eating habits for long term fitness success.', 'たんぱく質の品質、アミノ酸、消化、栄養摂取のタイミング、回復食、筋たんぱく質合成、バランスの取れた食事計画を学びながら、たんぱく質と筋肉栄養学を総合的に理解します。栄養が筋肉の修復、筋肉量の増加、運動後の回復、そして運動能力にどのような影響を与えるかを学びます。十分なたんぱく質を摂取し、筋力トレーニングを支え、体組成を改善し、長期的なフィットネス成功につながる健康的な食習慣を構築するための実践的な知識を身につけます。', 'Protein and Muscle Nutrition', 'Learn how protein supports muscle growth, recovery, strength development, and athletic performance through balanced nutrition and effective meal planning.', 'protein nutrition, muscle nutrition, protein intake, muscle recovery, amino acids, sports nutrition, healthy eating', 'storage/photos/products/18.webp', 999999, NULL, NULL, 'active', 38.00, 38, 38.00, 38.00, 0.00, 1, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(19, 'Healthy Weight Management', '健康的な体重管理', 'healthy-weight-management', 'Learn sustainable strategies for achieving and maintaining a healthy body weight through balanced nutrition, regular physical activity, healthy lifestyle habits, and realistic goal setting. Develop practical skills that support long term wellbeing without relying on restrictive dieting or short term solutions.', 'バランスの取れた栄養、定期的な運動、健康的な生活習慣、現実的な目標設定を通じて、健康的な体重を達成し維持するための持続可能な方法を学びます。極端な食事制限や短期的な方法に頼ることなく、長期的な健康を支える実践的なスキルを身につけます。', 'Develop a comprehensive understanding of healthy weight management by exploring calorie balance, nutrition planning, portion control, physical activity, behaviour change, metabolism, and long term lifestyle improvement. Learn how to create sustainable habits that support gradual weight management while maintaining muscle mass, improving energy levels, and promoting overall health. Gain practical knowledge for setting achievable goals, monitoring progress, overcoming common challenges, and maintaining healthy results through evidence based nutrition and fitness practices.', 'カロリーバランス、栄養計画、食事量の管理、身体活動、行動変容、代謝、そして長期的な生活習慣の改善について学びながら、健康的な体重管理を総合的に理解します。筋肉量を維持しながら体重を無理なく管理し、エネルギーレベルを高め、健康全般を向上させる持続可能な習慣を身につける方法を学びます。現実的な目標設定、進捗管理、課題への対応、そして科学的根拠に基づく栄養と運動を通じて健康的な結果を長期的に維持するための実践的な知識を習得します。', 'Healthy Weight Management', 'Learn sustainable weight management through balanced nutrition, healthy habits, regular exercise, and long term lifestyle strategies that promote overall wellbeing.', 'healthy weight management, weight control, balanced nutrition, healthy lifestyle, calorie balance, wellness, fitness nutrition', 'storage/photos/products/19.webp', 999999, NULL, NULL, 'active', 37.00, 37, 37.00, 37.00, 0.00, 1, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(20, 'Nutrition for Athletes', 'アスリートのための栄養学', 'nutrition-for-athletes', 'Develop a comprehensive understanding of athletic nutrition by learning how balanced eating, hydration, nutrient timing, and recovery strategies support training, competition, and overall performance. Build practical nutrition habits that enhance endurance, strength, recovery, and long term athletic success.', 'バランスの取れた食事、水分補給、栄養摂取のタイミング、回復戦略がトレーニングや競技、総合的な運動能力をどのように支えるかを学び、アスリートのための栄養学を総合的に理解します。持久力、筋力、回復力、そして長期的な競技パフォーマンスを向上させる実践的な栄養習慣を身につけます。', 'Develop advanced knowledge of nutrition for athletes by exploring performance nutrition, energy requirements, hydration strategies, macronutrient balance, micronutrient intake, meal planning, nutrient timing, and recovery nutrition. Learn how proper nutrition supports endurance, strength development, muscle recovery, immune function, and overall athletic performance. Gain practical experience creating evidence based nutrition plans that optimise training results, improve competition readiness, reduce fatigue, and promote long term health and physical performance.', 'パフォーマンス栄養学、エネルギー必要量、水分補給戦略、三大栄養素のバランス、微量栄養素の摂取、食事計画、栄養摂取のタイミング、回復栄養を学びながら、アスリートのための栄養学を深く理解します。適切な栄養が持久力、筋力向上、筋肉の回復、免疫機能、そして総合的な競技能力をどのように支えるかを学びます。科学的根拠に基づいた栄養プランを作成し、トレーニング成果を最大化し、試合への準備を整え、疲労を軽減し、長期的な健康と運動能力を向上させる実践的なスキルを習得します。', 'Nutrition for Athletes', 'Master sports nutrition strategies that improve athletic performance, recovery, endurance, strength, hydration, and long term health through evidence based nutrition planning.', 'nutrition for athletes, sports nutrition, athletic performance, hydration, recovery nutrition, meal planning, performance nutrition', 'storage/photos/products/20.webp', 999999, NULL, NULL, 'active', 39.00, 39, 39.00, 39.00, 0.00, 1, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(21, 'Certified Personal Trainer Prep', '認定パーソナルトレーナー試験対策', 'certified-personal-trainer-prep', 'Prepare for a career in personal training by developing a strong understanding of exercise principles, client communication, program design, safety guidelines, and professional coaching practices. Build the knowledge and confidence needed to support clients in achieving their health and fitness goals.', '運動の基礎理論、クライアントとのコミュニケーション、トレーニングプログラムの作成、安全管理、そしてプロフェッショナルな指導方法を学び、パーソナルトレーナーとしてのキャリアに向けた準備を行います。クライアントの健康とフィットネス目標を支援するために必要な知識と自信を身につけます。', 'Develop a comprehensive understanding of personal training by exploring exercise science fundamentals, client assessment, goal setting, program design, coaching techniques, communication skills, injury prevention, professional ethics, and business practices. Learn how certified personal trainers guide clients through safe and effective fitness programs while promoting long term health and motivation. Gain practical knowledge that prepares you for professional certification, improves coaching confidence, and supports success in the fitness industry.', '運動科学の基礎、クライアント評価、目標設定、トレーニングプログラム作成、コーチング技術、コミュニケーション能力、怪我予防、職業倫理、フィットネスビジネスについて学びながら、パーソナルトレーニングを総合的に理解します。認定パーソナルトレーナーが安全で効果的なプログラムを通じてクライアントを指導し、長期的な健康とモチベーションを支える方法を学びます。資格取得に向けた知識を深め、指導力を高め、フィットネス業界で活躍するための実践的なスキルを習得します。', 'Certified Personal Trainer Prep', 'Prepare for personal trainer certification by learning exercise science, coaching techniques, program design, client assessment, and professional fitness practices.', 'personal trainer, fitness certification, exercise science, coaching, fitness instructor, trainer preparation, personal training', 'storage/photos/products/21.webp', 999999, NULL, NULL, 'active', 40.00, 40, 40.00, 40.00, 0.00, 1, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(22, 'Exercise Science Fundamentals', '運動科学の基礎', 'exercise-science-fundamentals', 'Build a strong foundation in exercise science by learning how the human body responds to physical activity, resistance training, cardiovascular exercise, and recovery. Develop the knowledge required to design safe, effective, and evidence based fitness programs that improve health and physical performance.', '人体が運動、筋力トレーニング、有酸素運動、回復にどのように反応するかを学び、運動科学の基礎を身につけます。健康と身体能力を向上させる、安全で効果的かつ科学的根拠に基づいたフィットネスプログラムを設計するために必要な知識を習得します。', 'Develop a comprehensive understanding of exercise science by exploring human anatomy, physiology, biomechanics, kinesiology, energy systems, muscular adaptation, cardiovascular function, flexibility, recovery, and exercise programming principles. Learn how scientific concepts influence physical performance, injury prevention, movement quality, and long term fitness development. Gain practical knowledge that supports effective coaching, safe exercise prescription, and evidence based decision making for individuals with different fitness goals and abilities.', '人体解剖学、生理学、バイオメカニクス、運動学、エネルギーシステム、筋肉の適応、心肺機能、柔軟性、回復、運動プログラム設計の原則を学びながら、運動科学を総合的に理解します。科学的な知識が身体能力、怪我予防、動作の質、そして長期的なフィットネス向上にどのように影響するかを学びます。さまざまな目標や能力を持つ人々に対して、安全な運動指導と科学的根拠に基づくプログラムを提供するための実践的な知識を習得します。', 'Exercise Science Fundamentals', 'Learn the fundamentals of exercise science including anatomy, physiology, biomechanics, recovery, and evidence based fitness programming for better performance.', 'exercise science, anatomy, physiology, biomechanics, kinesiology, fitness education, exercise programming', 'storage/photos/products/22.webp', 999999, NULL, NULL, 'active', 39.00, 39, 39.00, 39.00, 0.00, 1, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(23, 'Client Assessment and Programming', 'クライアント評価とプログラム設計', 'client-assessment-and-programming', 'Learn how to assess clients, identify fitness goals, evaluate movement patterns, and design personalised exercise programs that support safe, effective, and measurable progress. Develop practical coaching skills that improve client outcomes and long term success.', 'クライアントを評価し、フィットネス目標を把握し、動作パターンを分析し、安全で効果的かつ測定可能な成果につながる個別トレーニングプログラムを作成する方法を学びます。クライアントの成果と長期的な成功を支える実践的なコーチングスキルを身につけます。', 'Develop a comprehensive understanding of client assessment and exercise programming by exploring health screening, fitness testing, movement analysis, goal setting, exercise selection, program progression, recovery planning, and performance evaluation. Learn how to create personalised fitness programs that address individual needs, improve physical performance, reduce injury risk, and support sustainable results. Gain practical knowledge for monitoring client progress, adapting training plans, and delivering professional coaching experiences that maximise long term health and fitness success.', '健康チェック、体力測定、動作分析、目標設定、エクササイズの選択、プログラムの進行管理、回復計画、パフォーマンス評価を学びながら、クライアント評価と運動プログラム設計を総合的に理解します。個々のニーズに合わせたトレーニングプログラムを作成し、身体能力を向上させ、怪我のリスクを軽減し、持続可能な成果を支える方法を学びます。クライアントの進捗を管理し、トレーニング内容を適切に調整し、長期的な健康とフィットネス成功を支える質の高い指導を提供するための実践的な知識を習得します。', 'Client Assessment and Programming', 'Master client assessment, fitness testing, personalised exercise programming, and progress tracking to deliver safe and effective fitness coaching.', 'client assessment, exercise programming, fitness testing, personalised training, coaching, fitness planning, movement analysis', 'storage/photos/products/23.webp', 999999, NULL, NULL, 'active', 38.00, 38, 38.00, 38.00, 0.00, 1, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(24, 'Group Fitness Coaching', 'グループフィットネス指導', 'group-fitness-coaching', 'Learn how to lead engaging group fitness sessions by developing coaching techniques, class planning skills, communication strategies, and participant motivation methods. Build the confidence to deliver safe, enjoyable, and effective workouts for individuals with different fitness levels.', 'コーチング技術、クラス設計、コミュニケーション方法、参加者をやる気にさせる指導法を学び、魅力的なグループフィットネスクラスを運営する方法を習得します。さまざまな体力レベルの参加者に対して、安全で楽しく効果的なトレーニングを提供できる自信を身につけます。', 'Develop a comprehensive understanding of group fitness coaching by exploring class programming, exercise instruction, leadership skills, communication techniques, participant engagement, safety procedures, music integration, class progression, and performance evaluation. Learn how to design structured group workouts that improve strength, endurance, mobility, and overall fitness while creating an enjoyable training environment. Gain practical coaching skills that help motivate participants, manage diverse fitness abilities, encourage consistency, and deliver professional group exercise experiences that support long term health and wellbeing.', 'クラスプログラムの作成、運動指導、リーダーシップ、コミュニケーション技術、参加者のモチベーション向上、安全管理、音楽の活用、クラスの進行、パフォーマンス評価を学びながら、グループフィットネス指導を総合的に理解します。筋力、持久力、柔軟性、総合的な体力を向上させる体系的なグループワークアウトを設計し、楽しく継続しやすい運動環境を作る方法を学びます。参加者のやる気を引き出し、異なる体力レベルに対応し、継続的な運動習慣を促進し、長期的な健康とウェルビーイングを支える質の高いグループレッスンを提供する実践的なコーチングスキルを習得します。', 'Group Fitness Coaching', 'Learn professional group fitness coaching, class planning, participant motivation, exercise instruction, and leadership skills for successful group training sessions.', 'group fitness coaching, fitness instructor, group exercise, class programming, fitness leadership, exercise coaching, group training', 'storage/photos/products/24.webp', 999999, NULL, NULL, 'active', 37.00, 37, 37.00, 37.00, 0.00, 1, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(25, 'Online Fitness Coaching', 'オンラインフィットネスコーチング', 'online-fitness-coaching', 'Learn how to deliver effective online fitness coaching through digital platforms, virtual training methods, client communication, program delivery, and remote progress tracking. Develop the skills required to coach clients effectively and build a successful online fitness service.', 'デジタルプラットフォーム、オンライン指導方法、クライアントとのコミュニケーション、プログラム提供、遠隔での進捗管理を通じて、効果的なオンラインフィットネスコーチングを提供する方法を学びます。クライアントを効果的に指導し、成功するオンラインフィットネスサービスを構築するために必要なスキルを身につけます。', 'Develop advanced skills in online fitness coaching by exploring virtual training systems, digital communication tools, remote program design, online client management, progress tracking, video coaching, fitness app integration, and online business strategies. Learn how to create personalised digital fitness experiences that maintain client engagement, improve accountability, and deliver measurable results. Gain practical knowledge for managing online clients, adapting training programs remotely, building professional relationships, and creating a scalable fitness coaching business in the digital fitness industry.', 'バーチャルトレーニングシステム、デジタルコミュニケーションツール、遠隔プログラム設計、オンラインクライアント管理、進捗管理、ビデオコーチング、フィットネスアプリ連携、オンラインビジネス戦略を学びながら、オンラインフィットネスコーチングの高度なスキルを習得します。クライアントの参加意欲を維持し、責任感を高め、測定可能な成果を提供する個別化されたデジタルフィットネス体験を作成する方法を学びます。オンライン顧客を管理し、遠隔でトレーニングプログラムを調整し、信頼関係を構築し、デジタルフィットネス業界で拡大可能なフィットネスビジネスを作るための実践的な知識を身につけます。', 'Online Fitness Coaching', 'Learn online fitness coaching strategies including virtual training, digital client management, remote programming, progress tracking, and building a successful online fitness business.', 'online fitness coaching, virtual training, fitness technology, remote coaching, digital fitness, online personal trainer, fitness business', 'storage/photos/products/25.webp', 999999, NULL, NULL, 'active', 40.00, 40, 40.00, 40.00, 0.00, 1, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `product_levels` (`id`, `course_id`, `skill_level`, `skill_level_jp`, `purpose`, `purpose_jp`, `learn_info`, `learn_info_jp`, `outcome`, `outcome_jp`, `price`, `price_jp`, `price_hk`, `price_in_points`, `created_at`, `updated_at`) VALUES
(1, 1, 'Beginner', '初級', 'Build a strong foundation in weight training by learning proper exercise techniques, basic movement patterns, workout structure, and essential safety practices. Develop the confidence to begin resistance training safely and effectively.', '正しいエクササイズフォーム、基本的な動作パターン、ワークアウトの構成、安全管理を学び、ウエイトトレーニングの基礎を築きます。安全かつ効果的に筋力トレーニングを始めるための自信と知識を身につけます。', 'Learn correct lifting techniques, equipment usage, warm up routines, exercise selection, repetition ranges, recovery principles, and beginner workout planning. Understand how resistance training improves strength, muscle development, posture, and overall health while avoiding common training mistakes.', '正しいリフティングフォーム、器具の使い方、ウォームアップ方法、種目の選択、反復回数、回復の基本、初心者向けプログラム作成を学びます。レジスタンストレーニングが筋力、筋肉の発達、姿勢、健康全般をどのように向上させるかを理解し、よくあるトレーニングミスを防ぐ方法を習得します。', 'Gain the confidence to perform fundamental weight training exercises safely, establish consistent workout habits, and build a strong fitness foundation for future strength and muscle development.', '基本的なウエイトトレーニングを安全に実践し、継続的な運動習慣を身につけ、将来の筋力向上と筋肥大につながる強固な基盤を築けるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(2, 1, 'Intermediate', '中級', 'Expand your weight training knowledge by improving exercise technique, increasing training intensity, and learning structured workout progression for continued strength development.', 'フォームを改善し、トレーニング強度を高め、体系的なプログラムの進め方を学ぶことで、筋力向上のための知識と実践力を高めます。', 'Learn progressive overload, exercise variation, volume management, training frequency, recovery strategies, and performance tracking. Develop efficient workout routines that improve strength, muscular endurance, and overall fitness performance.', '漸進的過負荷、種目のバリエーション、トレーニングボリューム管理、頻度、回復戦略、進捗管理を学びます。筋力、筋持久力、総合的な身体能力を向上させる効率的なプログラムを習得します。', 'Develop the ability to train independently using structured programs while continuously improving strength, movement quality, and exercise confidence.', '体系的なプログラムを活用して自立したトレーニングを行い、筋力、動作の質、自信を継続的に向上させることができます。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(3, 1, 'Advanced', '上級', 'Master advanced resistance training methods that maximise strength, muscle development, and long term physical performance through strategic program design.', '戦略的なプログラム設計を通じて、筋力、筋肥大、長期的な身体能力を最大限に高める高度なレジスタンストレーニングを学びます。', 'Explore advanced programming, periodisation, compound lifting, accessory exercises, training intensity management, recovery optimisation, and performance analysis. Learn evidence based methods for achieving consistent progress.', '高度なプログラム設計、ピリオダイゼーション、複合種目、補助種目、トレーニング強度管理、回復の最適化、パフォーマンス分析を学びます。科学的根拠に基づいた継続的な成長方法を習得します。', 'Confidently apply advanced weight training principles to maximise strength, muscle growth, exercise performance, and long term physical development.', '高度なウエイトトレーニング理論を実践し、筋力、筋肥大、競技能力、長期的な身体発達を最大限に高められるようになります。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(4, 1, 'Expert', '専門', 'Achieve expert level knowledge in weight training by integrating advanced coaching principles, scientific programming, and performance optimisation techniques.', '高度なコーチング理論、科学的プログラム設計、パフォーマンス最適化技術を統合し、ウエイトトレーニングの専門知識を習得します。', 'Master advanced exercise programming, biomechanical analysis, strength assessment, injury prevention, long term athlete development, coaching methodologies, and evidence based resistance training strategies.', '高度なプログラム設計、バイオメカニクス分析、筋力評価、怪我予防、長期的な身体能力開発、指導法、科学的根拠に基づく筋力トレーニング戦略を総合的に学びます。', 'Demonstrate professional level expertise in designing, evaluating, and optimising resistance training programs for long term strength, performance, and overall fitness success.', '長期的な筋力向上、競技能力向上、健康維持を目的としたレジスタンストレーニングプログラムを専門的に設計、評価、最適化できる知識と技能を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(5, 2, 'Beginner', '初級', 'Build a solid foundation for muscle growth by learning proper resistance training techniques, exercise selection, workout structure, and recovery principles. Develop healthy training habits that support consistent progress and long term fitness success.', '正しい筋力トレーニング技術、種目の選択、ワークアウトの構成、回復の基本を学び、筋肥大のための確かな基礎を築きます。継続的な成長と長期的な健康を支える正しいトレーニング習慣を身につけます。', 'Learn the fundamentals of muscle building including proper exercise form, repetition ranges, training frequency, recovery, nutrition basics, and beginner workout planning. Understand how muscles grow and how consistent training supports strength and physical development.', '正しいフォーム、反復回数、トレーニング頻度、回復、栄養の基礎、初心者向けプログラム作成など筋肥大の基本を学びます。筋肉が成長する仕組みと継続的なトレーニングが筋力と身体発達に与える影響を理解します。', 'Develop the confidence to perform effective muscle building workouts safely while creating a strong foundation for future strength and muscular development.', '安全で効果的な筋肥大トレーニングを実践し、将来の筋力向上と筋肉の発達につながる基礎を身につけます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(6, 2, 'Intermediate', '中級', 'Improve muscle development through structured workout programming, progressive overload, and effective recovery strategies that maximise consistent gains.', '体系的なトレーニングプログラム、漸進的過負荷、効果的な回復戦略を学び、継続的な筋肉の成長を促進します。', 'Learn advanced exercise selection, training volume management, workout splits, recovery techniques, muscle activation, and performance tracking to optimise muscle growth and training efficiency.', '高度な種目選択、トレーニングボリューム管理、分割法、回復技術、筋肉の活性化、進捗管理を学び、筋肥大とトレーニング効率を最大化します。', 'Gain the ability to build structured muscle building programs that improve strength, physique, and overall athletic performance.', '筋力、体格、身体能力を向上させる体系的な筋肥大プログラムを作成し実践できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(7, 2, 'Advanced', '上級', 'Master advanced hypertrophy training methods using scientific programming, training intensity management, and recovery optimisation techniques.', '科学的なプログラム設計、トレーニング強度管理、回復最適化を活用し、高度な筋肥大トレーニングを習得します。', 'Explore advanced hypertrophy programming, exercise sequencing, intensity techniques, volume cycling, recovery management, nutrition support, and evidence based training strategies for maximum muscle growth.', '高度な筋肥大プログラム、種目の順序、強度テクニック、ボリュームサイクル、回復管理、栄養サポート、科学的根拠に基づく筋肥大戦略を学びます。', 'Apply advanced muscle building principles to maximise muscular size, strength, training efficiency, and long term physical development.', '高度な筋肥大理論を実践し、筋肉量、筋力、トレーニング効率、長期的な身体発達を最大限に高められるようになります。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(8, 2, 'Expert', '専門', 'Achieve professional level expertise in muscle building by integrating advanced coaching principles, scientific research, and long term training strategies.', '高度な指導法、科学的研究、長期的なトレーニング戦略を統合し、筋肥大トレーニングの専門知識を習得します。', 'Master advanced hypertrophy programming, biomechanics, muscular adaptation, exercise analysis, recovery optimisation, coaching methodologies, and evidence based strength development techniques.', '高度な筋肥大プログラム、バイオメカニクス、筋肉の適応、動作分析、回復最適化、コーチング手法、科学的根拠に基づく筋力向上技術を総合的に学びます。', 'Demonstrate expert level knowledge in designing and optimising muscle building programs that deliver sustainable strength, muscle growth, and high performance results.', '持続可能な筋力向上、筋肥大、高いパフォーマンスを実現する筋肥大プログラムを専門的に設計、最適化できる知識と技術を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(9, 3, 'Beginner', '初級', 'Build a strong foundation in powerlifting by learning the fundamental techniques for the squat, bench press, and deadlift. Develop proper lifting mechanics, safety practices, and confidence while preparing for long term strength development.', 'スクワット、ベンチプレス、デッドリフトの基本技術を学び、パワーリフティングの基礎を築きます。正しいフォーム、安全なトレーニング方法、そして長期的な筋力向上に向けた自信を身につけます。', 'Learn correct techniques for the three main competition lifts, proper warm up routines, lifting safety, equipment usage, training frequency, recovery principles, and beginner programming. Understand how consistent practice improves strength and movement quality.', 'パワーリフティングの三種目であるスクワット、ベンチプレス、デッドリフトの正しいフォーム、ウォームアップ、安全管理、器具の使い方、トレーニング頻度、回復方法、初心者向けプログラムを学びます。継続的な練習が筋力と動作の質を向上させる仕組みを理解します。', 'Develop the confidence to safely perform the primary powerlifting movements while establishing a strong foundation for long term strength and performance improvement.', 'パワーリフティングの基本種目を安全に実践し、長期的な筋力向上と競技力向上のための基礎を身につけます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(10, 3, 'Intermediate', '中級', 'Improve your powerlifting performance through structured strength programming, progressive overload, technical refinement, and effective recovery strategies.', '体系的な筋力プログラム、漸進的過負荷、フォーム改善、回復戦略を学び、パワーリフティングのパフォーマンスを向上させます。', 'Learn advanced lifting techniques, training cycles, accessory exercises, mobility work, fatigue management, recovery planning, and performance tracking to improve maximum strength across all competition lifts.', '高度なリフティング技術、トレーニングサイクル、補助種目、モビリティ向上、疲労管理、回復計画、進捗管理を学び、三種目すべての最大筋力を高めます。', 'Develop the ability to follow structured strength programs that consistently improve lifting performance, technique, and overall physical strength.', '体系的な筋力プログラムを実践し、リフティング技術、競技力、総合的な筋力を継続的に向上させることができます。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(11, 3, 'Advanced', '上級', 'Master advanced powerlifting techniques through scientific programming, periodisation, competition preparation, and performance optimisation strategies.', '科学的なプログラム設計、ピリオダイゼーション、大会準備、パフォーマンス最適化戦略を通じて高度なパワーリフティング技術を習得します。', 'Explore advanced strength programming, competition peaking, biomechanical analysis, bar path optimisation, recovery management, accessory programming, and evidence based performance improvement techniques.', '高度な筋力プログラム、大会ピーキング、バイオメカニクス分析、バーベル軌道の最適化、回復管理、補助種目の設計、科学的根拠に基づく筋力向上法を学びます。', 'Apply advanced powerlifting principles to maximise strength, improve competition performance, and achieve long term athletic development.', '高度なパワーリフティング理論を実践し、筋力を最大化し、大会成績と長期的な競技能力を向上させることができます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(12, 3, 'Expert', '専門', 'Achieve expert level knowledge in powerlifting by integrating advanced coaching methods, scientific analysis, competition strategies, and long term athlete development.', '高度な指導法、科学的分析、大会戦略、長期的な競技者育成を統合し、パワーリフティングの専門知識を習得します。', 'Master elite level strength programming, biomechanics, competition coaching, performance analysis, recovery optimisation, injury prevention, and evidence based training methodologies used by experienced powerlifters.', 'トップレベルの筋力プログラム、バイオメカニクス、大会指導、パフォーマンス分析、回復最適化、怪我予防、経験豊富な競技者が活用する科学的トレーニング手法を総合的に学びます。', 'Demonstrate professional expertise in designing, evaluating, and optimising powerlifting programs that maximise competitive strength and long term athletic performance.', '競技レベルの筋力と長期的な身体能力を最大限に高めるパワーリフティングプログラムを専門的に設計、評価、最適化できる知識と技術を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(13, 4, 'Beginner', '初級', 'Develop a strong foundation in functional strength training by learning movement based exercises that improve balance, coordination, mobility, stability, and overall physical performance for everyday activities.', '日常生活やスポーツに役立つ動作を中心としたトレーニングを学び、バランス、協調性、可動性、安定性、総合的な身体能力を向上させるための基礎を築きます。', 'Learn fundamental movement patterns, bodyweight exercises, core stability, balance training, mobility drills, proper exercise technique, warm up routines, and recovery principles. Understand how functional training improves strength, movement efficiency, injury prevention, and daily performance.', '基本的な動作パターン、自重トレーニング、体幹の安定性、バランストレーニング、モビリティドリル、正しいフォーム、ウォームアップ、回復方法を学びます。機能的トレーニングが筋力、動作効率、怪我予防、日常生活のパフォーマンス向上にどのように役立つかを理解します。', 'Develop the confidence to perform functional exercises safely while improving movement quality, stability, strength, and overall physical fitness.', '機能的トレーニングを安全に実践し、動作の質、安定性、筋力、総合的な身体能力を向上させることができます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(14, 4, 'Intermediate', '中級', 'Improve functional fitness through progressive movement training, strength development, coordination exercises, and structured workout programming.', '段階的な動作トレーニング、筋力向上、協調性トレーニング、体系的なワークアウトを通じて機能的な身体能力を高めます。', 'Learn advanced movement patterns, unilateral exercises, rotational movements, stability training, agility drills, recovery planning, and performance tracking. Build efficient workouts that improve strength, mobility, endurance, and athletic performance.', '高度な動作パターン、片側トレーニング、回旋動作、安定性トレーニング、敏捷性ドリル、回復計画、進捗管理を学びます。筋力、柔軟性、持久力、運動能力を高める効率的なプログラムを習得します。', 'Develop the ability to perform more complex functional movements while improving athletic performance, coordination, and movement efficiency.', 'より高度な機能的動作を実践し、運動能力、協調性、動作効率を継続的に向上させることができます。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(15, 4, 'Advanced', '上級', 'Master advanced functional strength training techniques that integrate strength, mobility, power, balance, and movement efficiency for peak physical performance.', '筋力、柔軟性、パワー、バランス、動作効率を組み合わせた高度な機能的トレーニングを習得し、最高の身体能力を目指します。', 'Explore advanced movement programming, explosive training, multi directional exercises, functional power development, mobility optimisation, recovery management, and evidence based performance improvement strategies.', '高度な動作プログラム、爆発的トレーニング、多方向運動、機能的パワー向上、柔軟性の最適化、回復管理、科学的根拠に基づくパフォーマンス向上法を学びます。', 'Apply advanced functional training principles to maximise strength, movement quality, athletic performance, and long term physical resilience.', '高度な機能的トレーニング理論を活用し、筋力、動作の質、競技能力、長期的な身体機能を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(16, 4, 'Expert', '専門', 'Achieve expert level knowledge in functional strength training through advanced coaching methods, movement analysis, scientific programming, and performance optimisation.', '高度なコーチング技術、動作分析、科学的プログラム設計、パフォーマンス最適化を通じて、機能的筋力トレーニングの専門知識を習得します。', 'Master advanced movement assessment, biomechanics, functional programming, athletic development, injury prevention, coaching methodologies, and evidence based performance strategies for diverse populations.', '高度な動作評価、バイオメカニクス、機能的プログラム設計、競技力向上、怪我予防、コーチング手法、さまざまな対象者に対応する科学的トレーニング戦略を総合的に学びます。', 'Demonstrate professional expertise in designing and optimising functional strength training programs that improve movement quality, physical performance, and long term health.', '動作の質、身体能力、長期的な健康を向上させる機能的筋力トレーニングプログラムを専門的に設計、評価、最適化できる知識と技術を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(17, 5, 'Beginner', '初級', 'Build a strong foundation in hypertrophy training by learning the principles of muscle growth, proper exercise technique, training volume, recovery, and nutrition. Develop effective habits that support safe and consistent muscular development.', '筋肥大トレーニングの基本原則、正しいフォーム、トレーニング量、回復、栄養について学び、筋肉の成長を支える基礎を築きます。安全で継続的な筋肉の発達を支える習慣を身につけます。', 'Learn the science of muscle growth, proper lifting mechanics, exercise selection, repetition ranges, recovery strategies, nutrition basics, and beginner workout planning. Understand how structured resistance training promotes long term muscular development.', '筋肉が成長する仕組み、正しいフォーム、種目選択、反復回数、回復方法、栄養の基礎、初心者向けトレーニング計画を学びます。体系的なレジスタンストレーニングが長期的な筋肥大を促進する仕組みを理解します。', 'Develop the knowledge and confidence to begin hypertrophy focused training safely while building a solid foundation for future muscle growth and strength.', '安全に筋肥大トレーニングを開始し、将来の筋肉増強と筋力向上につながる確かな基礎を身につけます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(18, 5, 'Intermediate', '中級', 'Improve muscular development through progressive overload, advanced workout programming, exercise variation, and recovery management designed to maximise consistent hypertrophy.', '漸進的過負荷、高度なトレーニングプログラム、種目のバリエーション、回復管理を学び、継続的な筋肥大を促進します。', 'Learn advanced hypertrophy programming, training splits, volume management, intensity techniques, exercise sequencing, nutrition planning, and performance tracking to improve muscular size and training efficiency.', '高度な筋肥大プログラム、トレーニング分割法、ボリューム管理、強度テクニック、種目の順序、栄養計画、進捗管理を学び、筋肉量とトレーニング効率を高めます。', 'Develop the ability to create structured hypertrophy programs that maximise muscle growth, improve strength, and enhance overall physical development.', '筋肥大を最大化し、筋力と身体能力を向上させる体系的なトレーニングプログラムを作成できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(19, 5, 'Advanced', '上級', 'Master advanced hypertrophy training techniques using scientific programming, periodisation, recovery optimisation, and evidence based muscle building strategies.', '科学的なプログラム設計、ピリオダイゼーション、回復最適化、科学的根拠に基づく筋肥大戦略を活用し、高度な筋肥大トレーニングを習得します。', 'Explore advanced hypertrophy systems, training intensity management, volume cycling, biomechanical optimisation, recovery strategies, nutrition support, and long term muscle development techniques.', '高度な筋肥大システム、トレーニング強度管理、ボリュームサイクル、バイオメカニクスの最適化、回復戦略、栄養サポート、長期的な筋肉発達手法を学びます。', 'Apply advanced hypertrophy principles to maximise muscular size, improve training efficiency, and achieve sustainable long term physical development.', '高度な筋肥大理論を実践し、筋肉量、トレーニング効率、長期的な身体発達を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(20, 5, 'Expert', '専門', 'Achieve professional level expertise in hypertrophy training by integrating advanced coaching methods, scientific research, performance analysis, and long term programming strategies.', '高度な指導法、科学的研究、パフォーマンス分析、長期的なプログラム設計を統合し、筋肥大トレーニングの専門知識を習得します。', 'Master elite hypertrophy programming, biomechanics, muscular adaptation, advanced coaching techniques, recovery optimisation, nutrition integration, and evidence based strategies for maximum muscle development.', '高度な筋肥大プログラム、バイオメカニクス、筋肉の適応、専門的な指導技術、回復最適化、栄養管理、科学的根拠に基づく最大限の筋肉発達戦略を総合的に学びます。', 'Demonstrate expert level ability to design, evaluate, and optimise advanced hypertrophy programs that maximise muscle growth, performance, and long term athletic development.', '筋肉の成長、競技力、長期的な身体能力を最大限に高める高度な筋肥大プログラムを専門的に設計、評価、最適化できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(21, 6, 'Beginner', '初級', 'Build a strong foundation for healthy fat loss by learning the principles of calorie balance, exercise planning, nutrition, and sustainable lifestyle habits. Develop practical strategies that support safe and consistent weight management.', 'カロリーバランス、運動計画、栄養、持続可能な生活習慣の基本を学び、安全で継続的な脂肪減少を実現するための基礎を築きます。', 'Learn the fundamentals of fat loss including energy balance, healthy eating habits, beginner exercise routines, metabolism basics, recovery, hydration, and goal setting. Understand how consistent habits contribute to long term weight management and improved health.', 'エネルギーバランス、健康的な食習慣、初心者向け運動、代謝の基礎、回復、水分補給、目標設定など脂肪減少の基本を学びます。継続的な習慣が長期的な体重管理と健康改善につながる仕組みを理解します。', 'Develop the confidence to begin a structured fat loss journey while building healthy habits that support long term fitness and wellbeing.', '健康的な習慣を身につけながら、安全で継続的な脂肪減少プログラムを実践できるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(22, 6, 'Intermediate', '中級', 'Improve fat loss results through structured nutrition planning, progressive training, activity tracking, and recovery strategies that promote sustainable body composition improvements.', '体系的な栄養計画、段階的なトレーニング、活動量管理、回復戦略を学び、持続可能な体脂肪減少を実現します。', 'Learn advanced calorie management, macronutrient planning, cardio programming, resistance training for fat loss, recovery techniques, behavioural strategies, and progress monitoring to optimise healthy weight reduction.', '高度なカロリー管理、栄養バランス、脂肪燃焼のための有酸素運動と筋力トレーニング、回復方法、行動改善、進捗管理を学びます。', 'Develop the ability to create balanced fat loss programs that improve body composition, fitness, and long term health.', '体脂肪を減らし、身体組成、体力、健康を継続的に改善するプログラムを作成できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(23, 6, 'Advanced', '上級', 'Master advanced fat loss strategies using scientific nutrition planning, performance based training, metabolic optimisation, and sustainable lifestyle management.', '科学的な栄養管理、パフォーマンス重視のトレーニング、代謝の最適化、持続可能な生活管理を組み合わせた高度な脂肪減少戦略を習得します。', 'Explore advanced nutrition strategies, training periodisation, metabolic adaptation, body composition analysis, recovery optimisation, behavioural coaching, and evidence based fat loss techniques.', '高度な栄養戦略、トレーニングのピリオダイゼーション、代謝適応、身体組成分析、回復最適化、行動指導、科学的根拠に基づく脂肪減少法を学びます。', 'Apply advanced fat loss principles to maximise body composition improvements while maintaining strength, performance, and long term health.', '筋力や身体能力を維持しながら体脂肪を効率的に減らし、長期的な健康を維持する高度な知識を身につけます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(24, 6, 'Expert', '専門', 'Achieve expert level knowledge in fat loss coaching through advanced nutrition science, exercise programming, metabolic health, and long term behaviour change strategies.', '高度な栄養学、運動プログラム、代謝管理、長期的な行動変容を統合し、脂肪減少指導の専門知識を習得します。', 'Master advanced fat loss programming, nutrition periodisation, metabolic health management, body composition assessment, coaching methodologies, recovery optimisation, and evidence based weight management strategies.', '高度な脂肪減少プログラム、栄養ピリオダイゼーション、代謝管理、身体組成評価、コーチング手法、回復最適化、科学的根拠に基づく体重管理戦略を総合的に学びます。', 'Demonstrate professional expertise in designing and optimising fat loss programs that deliver sustainable body composition improvements and long term health outcomes.', '持続可能な脂肪減少と健康改善を実現する専門的なプログラムを設計、評価、最適化できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(25, 7, 'Beginner', '初級', 'Build a strong foundation in high intensity interval training by learning proper exercise techniques, workout structure, pacing, and recovery principles. Develop safe training habits that improve cardiovascular fitness, endurance, and overall health.', '高強度インターバルトレーニングの基本を学び、正しいフォーム、ワークアウト構成、ペース配分、回復方法を理解します。心肺機能、持久力、健康を向上させる安全なトレーニング習慣を身につけます。', 'Learn the fundamentals of high intensity interval training including warm up routines, work to rest ratios, bodyweight exercises, cardiovascular conditioning, recovery strategies, and beginner workout planning. Understand how HIIT improves endurance, burns calories, and supports overall fitness.', 'ウォームアップ、運動と休息の比率、自重トレーニング、心肺機能向上、回復方法、初心者向けプログラムなど、高強度インターバルトレーニングの基本を学びます。HIITが持久力向上、カロリー消費、総合的な体力向上に役立つ仕組みを理解します。', 'Develop the confidence to complete safe and effective HIIT workouts while building endurance, improving fitness, and supporting long term health.', '安全で効果的なHIITトレーニングを実践し、持久力、体力、長期的な健康を向上させる基礎を身につけます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(26, 7, 'Intermediate', '中級', 'Improve cardiovascular fitness and athletic performance through structured HIIT programming, progressive intensity, exercise variation, and recovery management.', '体系的なHIITプログラム、段階的な強度向上、多様なエクササイズ、回復管理を学び、心肺機能と運動能力を向上させます。', 'Learn advanced interval programming, exercise sequencing, intensity control, heart rate monitoring, recovery planning, performance tracking, and workout progression to maximise training efficiency.', '高度なインターバル設計、種目の組み合わせ、強度管理、心拍数モニタリング、回復計画、進捗管理、トレーニングの進化方法を学び、HIITの効果を最大化します。', 'Develop the ability to perform structured HIIT workouts that improve endurance, cardiovascular health, calorie expenditure, and athletic performance.', '持久力、心肺機能、カロリー消費、運動能力を向上させる体系的なHIITプログラムを実践できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(27, 7, 'Advanced', '上級', 'Master advanced HIIT training techniques through scientific programming, energy system development, recovery optimisation, and performance based conditioning.', '科学的なプログラム設計、エネルギーシステムの強化、回復最適化、競技力向上を目的とした高度なHIITトレーニングを習得します。', 'Explore advanced interval programming, anaerobic conditioning, aerobic capacity development, explosive movement training, recovery optimisation, fatigue management, and evidence based conditioning strategies.', '高度なインターバルプログラム、無酸素能力、有酸素能力向上、爆発的動作トレーニング、回復最適化、疲労管理、科学的根拠に基づくコンディショニング戦略を学びます。', 'Apply advanced HIIT principles to maximise endurance, conditioning, athletic performance, and long term physical fitness.', '高度なHIIT理論を活用し、持久力、コンディショニング、運動能力、長期的な体力を最大限に高めます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(28, 7, 'Expert', '専門', 'Achieve expert level knowledge in HIIT coaching by integrating advanced exercise science, performance analysis, programming strategies, and long term athlete development.', '高度な運動科学、パフォーマンス分析、プログラム設計、長期的な競技者育成を統合し、HIIT指導の専門知識を習得します。', 'Master elite HIIT programming, exercise physiology, conditioning assessment, recovery management, coaching methodologies, performance optimisation, and evidence based interval training techniques.', '高度なHIITプログラム、運動生理学、コンディショニング評価、回復管理、コーチング手法、パフォーマンス最適化、科学的根拠に基づくインターバルトレーニング技術を総合的に学びます。', 'Demonstrate professional expertise in designing and optimising HIIT training programs that maximise conditioning, athletic performance, and long term physical development.', 'コンディショニング、競技力、長期的な身体能力を最大化するHIITプログラムを専門的に設計、評価、最適化できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(29, 8, 'Beginner', '初級', 'Build a strong foundation in cardiovascular training by learning safe aerobic exercises, proper workout intensity, heart health principles, and endurance development techniques. Develop consistent habits that support healthy weight loss and long term fitness.', '安全な有酸素運動、適切な運動強度、心臓の健康、持久力向上の基本を学び、有酸素トレーニングの基礎を築きます。健康的な減量と長期的な体力向上を支える継続的な習慣を身につけます。', 'Learn the fundamentals of cardiovascular exercise including walking, jogging, cycling, heart rate monitoring, workout planning, recovery strategies, and beginner endurance training. Understand how regular cardio supports fat loss, cardiovascular health, and overall wellbeing.', 'ウォーキング、ジョギング、サイクリング、心拍数管理、トレーニング計画、回復方法、初心者向け持久力トレーニングなど、有酸素運動の基本を学びます。継続的な有酸素運動が脂肪燃焼、心肺機能、健康全般に与える効果を理解します。', 'Develop the confidence to perform effective cardiovascular workouts that improve endurance, support healthy weight loss, and enhance overall fitness.', '持久力を向上させ、健康的な減量をサポートし、総合的な体力を高める有酸素運動を安全に実践できるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(30, 8, 'Intermediate', '中級', 'Improve cardiovascular fitness through structured training plans, progressive endurance development, heart rate management, and workout variety designed to maximise fat loss.', '体系的なトレーニング計画、段階的な持久力向上、心拍数管理、多様なワークアウトを学び、脂肪燃焼と心肺機能を効率的に高めます。', 'Learn interval cardio, endurance programming, training intensity management, calorie expenditure strategies, recovery planning, performance monitoring, and exercise progression for sustainable fitness improvement.', 'インターバルトレーニング、持久力向上プログラム、運動強度管理、カロリー消費戦略、回復計画、進捗管理、運動の発展方法を学び、持続的な体力向上を目指します。', 'Develop the ability to create structured cardio programs that improve endurance, cardiovascular health, and healthy body composition.', '持久力、心肺機能、健康的な身体づくりを支える体系的な有酸素運動プログラムを実践できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(31, 8, 'Advanced', '上級', 'Master advanced cardiovascular training techniques through scientific endurance programming, aerobic capacity development, recovery optimisation, and performance improvement strategies.', '科学的な持久力プログラム、有酸素能力向上、回復最適化、パフォーマンス向上戦略を通じて高度な有酸素トレーニングを習得します。', 'Explore advanced endurance programming, aerobic and anaerobic conditioning, heart rate zone training, recovery management, metabolic efficiency, and evidence based cardiovascular performance strategies.', '高度な持久力プログラム、有酸素および無酸素能力向上、心拍ゾーントレーニング、回復管理、代謝効率向上、科学的根拠に基づく有酸素運動戦略を学びます。', 'Apply advanced cardiovascular training principles to maximise endurance, calorie expenditure, physical performance, and long term health.', '高度な有酸素トレーニング理論を活用し、持久力、消費カロリー、身体能力、長期的な健康を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(32, 8, 'Expert', '専門', 'Achieve expert level knowledge in cardiovascular training through advanced exercise physiology, endurance coaching, scientific programming, and long term performance development.', '高度な運動生理学、持久力コーチング、科学的プログラム設計、長期的なパフォーマンス向上を統合し、有酸素トレーニングの専門知識を習得します。', 'Master elite cardiovascular programming, endurance assessment, exercise physiology, recovery optimisation, coaching methodologies, metabolic conditioning, and evidence based endurance development strategies.', '高度な有酸素トレーニングプログラム、持久力評価、運動生理学、回復最適化、コーチング手法、代謝コンディショニング、科学的根拠に基づく持久力向上戦略を総合的に学びます。', 'Demonstrate professional expertise in designing and optimising cardiovascular training programs that maximise endurance, heart health, and long term physical performance.', '持久力、心肺機能、長期的な身体能力を最大限に高める有酸素トレーニングプログラムを専門的に設計、評価、最適化できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(33, 9, 'Beginner', '初級', 'Build a strong foundation in metabolic conditioning by learning full body training techniques that improve endurance, strength, cardiovascular fitness, and calorie expenditure. Develop safe workout habits that support overall fitness and long term health.', '全身を使ったトレーニングを学び、持久力、筋力、心肺機能、カロリー消費を向上させるメタボリックコンディショニングの基礎を築きます。総合的な体力と長期的な健康を支える安全なトレーニング習慣を身につけます。', 'Learn the fundamentals of metabolic conditioning including circuit training, bodyweight exercises, interval training, workout pacing, recovery strategies, and beginner programming. Understand how metabolic conditioning improves energy systems, burns calories, and supports overall fitness.', 'サーキットトレーニング、自重トレーニング、インターバルトレーニング、ペース配分、回復方法、初心者向けプログラムなど、メタボリックコンディショニングの基本を学びます。エネルギーシステムの向上、カロリー消費、総合的な体力向上の仕組みを理解します。', 'Develop the confidence to perform metabolic conditioning workouts safely while improving endurance, strength, and overall physical fitness.', 'メタボリックコンディショニングを安全に実践し、持久力、筋力、総合的な身体能力を向上させることができます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(34, 9, 'Intermediate', '中級', 'Improve fitness through structured metabolic conditioning workouts that combine strength, endurance, speed, and cardiovascular training for maximum efficiency.', '筋力、持久力、スピード、心肺機能を組み合わせた体系的なメタボリックコンディショニングを学び、効率的に身体能力を向上させます。', 'Learn advanced circuit programming, interval design, work and rest management, movement sequencing, recovery planning, performance tracking, and progressive workout development to improve conditioning.', '高度なサーキット設計、インターバル構成、運動と休息の管理、種目の組み合わせ、回復計画、進捗管理、段階的なトレーニング設計を学びます。', 'Develop the ability to complete structured metabolic conditioning programs that improve endurance, strength, calorie expenditure, and athletic performance.', '持久力、筋力、カロリー消費、運動能力を高める体系的なメタボリックコンディショニングプログラムを実践できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(35, 9, 'Advanced', '上級', 'Master advanced metabolic conditioning through scientific workout programming, energy system development, recovery optimisation, and performance enhancement techniques.', '科学的なプログラム設計、エネルギーシステムの強化、回復最適化、パフォーマンス向上技術を活用し、高度なメタボリックコンディショニングを習得します。', 'Explore advanced conditioning systems, high intensity circuits, aerobic and anaerobic development, recovery optimisation, fatigue management, performance monitoring, and evidence based training strategies.', '高度なコンディショニングシステム、高強度サーキット、有酸素および無酸素能力向上、回復最適化、疲労管理、パフォーマンス分析、科学的根拠に基づくトレーニング戦略を学びます。', 'Apply advanced metabolic conditioning principles to maximise endurance, work capacity, athletic performance, and long term physical development.', '高度なメタボリックコンディショニング理論を実践し、持久力、作業能力、競技力、長期的な身体能力を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(36, 9, 'Expert', '専門', 'Achieve expert level knowledge in metabolic conditioning through advanced exercise science, performance coaching, scientific programming, and long term athletic development.', '高度な運動科学、パフォーマンスコーチング、科学的プログラム設計、長期的な競技者育成を統合し、メタボリックコンディショニングの専門知識を習得します。', 'Master elite metabolic conditioning programming, exercise physiology, energy system assessment, recovery optimisation, coaching methodologies, performance analysis, and evidence based conditioning strategies.', '高度なメタボリックコンディショニングプログラム、運動生理学、エネルギーシステム評価、回復最適化、コーチング手法、パフォーマンス分析、科学的根拠に基づくコンディショニング戦略を総合的に学びます。', 'Demonstrate professional expertise in designing and optimising metabolic conditioning programs that maximise endurance, athletic performance, and long term physical fitness.', '持久力、競技能力、長期的な身体能力を最大限に高めるメタボリックコンディショニングプログラムを専門的に設計、評価、最適化できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(37, 10, 'Beginner', '初級', 'Begin your body transformation journey by building healthy exercise, nutrition, and lifestyle habits that promote steady progress. Learn how to establish realistic goals, improve fitness, and create sustainable routines for long term success.', '健康的な運動、栄養、生活習慣を身につけ、着実な身体改善を目指すボディトランスフォーメーションの基礎を学びます。現実的な目標設定、体力向上、長期的な成功につながる持続可能な習慣を身につけます。', 'Learn the fundamentals of body transformation including resistance training, cardiovascular exercise, healthy nutrition, recovery, hydration, sleep, and progress tracking. Understand how consistent habits create sustainable improvements in body composition and overall health.', '筋力トレーニング、有酸素運動、健康的な栄養、回復、水分補給、睡眠、進捗管理など、ボディトランスフォーメーションの基本を学びます。継続的な習慣が身体組成と健康全般を改善する仕組みを理解します。', 'Develop the confidence to follow a structured transformation plan while improving strength, fitness, body composition, and overall wellbeing.', '体系的なボディトランスフォーメーションプログラムを実践し、筋力、体力、身体組成、健康を向上させる基礎を身につけます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(38, 10, 'Intermediate', '中級', 'Accelerate your body transformation through structured workout programming, balanced nutrition planning, progressive training, and effective recovery strategies.', '体系的なトレーニングプログラム、バランスの取れた栄養計画、段階的な運動、回復戦略を学び、身体改善をさらに加速させます。', 'Learn advanced workout planning, calorie management, strength progression, cardiovascular programming, recovery optimisation, behavioural consistency, and performance tracking to maximise transformation results.', '高度なトレーニング計画、カロリー管理、筋力向上、有酸素運動プログラム、回復最適化、継続的な習慣づくり、進捗管理を学び、身体改善を最大化します。', 'Develop the ability to create balanced transformation plans that improve fitness, body composition, strength, and long term health.', '体力、身体組成、筋力、長期的な健康を改善する体系的なボディトランスフォーメーションプログラムを作成できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(39, 10, 'Advanced', '上級', 'Master advanced body transformation strategies using scientific training methods, nutrition planning, recovery optimisation, and performance based programming.', '科学的なトレーニング、栄養管理、回復最適化、パフォーマンス重視のプログラム設計を活用し、高度なボディトランスフォーメーション戦略を習得します。', 'Explore advanced strength programming, body composition analysis, nutrition periodisation, metabolic optimisation, recovery management, behavioural coaching, and evidence based transformation strategies.', '高度な筋力プログラム、身体組成分析、栄養ピリオダイゼーション、代謝最適化、回復管理、行動コーチング、科学的根拠に基づく身体改善戦略を学びます。', 'Apply advanced transformation principles to maximise body composition improvements while maintaining performance, strength, and long term health.', '高度なボディトランスフォーメーション理論を活用し、筋力や身体能力を維持しながら身体組成と健康を最大限に改善します。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(40, 10, 'Expert', '専門', 'Achieve expert level knowledge in body transformation coaching by integrating advanced exercise science, nutrition strategies, behavioural psychology, and long term lifestyle planning.', '高度な運動科学、栄養戦略、行動心理学、長期的なライフスタイル設計を統合し、ボディトランスフォーメーション指導の専門知識を習得します。', 'Master advanced body transformation programming, nutrition coaching, metabolic health management, recovery optimisation, client assessment, coaching methodologies, and evidence based strategies for sustainable physical transformation.', '高度なボディトランスフォーメーションプログラム、栄養指導、代謝管理、回復最適化、クライアント評価、コーチング手法、持続可能な身体改善のための科学的根拠に基づく戦略を総合的に学びます。', 'Demonstrate professional expertise in designing and optimising body transformation programs that deliver sustainable improvements in body composition, health, fitness, and long term performance.', '身体組成、健康、体力、長期的な身体能力を持続的に向上させるボディトランスフォーメーションプログラムを専門的に設計、評価、最適化できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(41, 11, 'Beginner', '初級', 'Build a strong foundation in yoga by learning essential poses, breathing techniques, posture alignment, and relaxation methods. Develop flexibility, balance, body awareness, and healthy movement habits that support long term physical and mental wellbeing.', '基本的なヨガのポーズ、呼吸法、姿勢の整え方、リラクゼーションを学び、ヨガの基礎を築きます。柔軟性、バランス、身体意識を高め、心身の健康を支える習慣を身につけます。', 'Learn beginner friendly yoga poses, breathing exercises, stretching techniques, balance training, relaxation practices, and proper body alignment. Understand how regular yoga improves flexibility, mobility, posture, stress management, and overall wellness.', '初心者向けヨガポーズ、呼吸法、ストレッチ、バランストレーニング、リラクゼーション、正しい姿勢を学びます。継続的なヨガが柔軟性、可動域、姿勢改善、ストレス軽減、健康全般に役立つ仕組みを理解します。', 'Develop the confidence to practice beginner yoga safely while improving flexibility, posture, relaxation, and overall physical wellbeing.', '初心者向けヨガを安全に実践し、柔軟性、姿勢、リラクゼーション、身体全体の健康を向上させることができます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(42, 11, 'Intermediate', '中級', 'Improve your yoga practice through structured sequences, enhanced flexibility, breathing control, balance development, and mindful movement techniques.', '体系的なヨガシーケンス、柔軟性向上、呼吸コントロール、バランス強化、マインドフルな動きを学び、ヨガの実践を深めます。', 'Learn intermediate yoga flows, standing balances, flexibility exercises, breathing coordination, core engagement, recovery techniques, and mindful practice routines to improve overall movement quality.', '中級ヨガフロー、立位バランス、柔軟性向上、呼吸との連動、体幹強化、回復法、マインドフルな実践方法を学び、身体の動きの質を高めます。', 'Develop the ability to perform structured yoga sequences that improve flexibility, balance, body awareness, and physical fitness.', '柔軟性、バランス、身体意識、体力を向上させる体系的なヨガシーケンスを実践できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(43, 11, 'Advanced', '上級', 'Master advanced yoga techniques through challenging postures, breath control, mobility development, meditation, and long term physical and mental conditioning.', '高度なヨガポーズ、呼吸法、柔軟性向上、瞑想、心身のコンディショニングを通じて上級ヨガを習得します。', 'Explore advanced yoga sequences, deep stretching, inversion preparation, advanced breathing practices, meditation techniques, recovery methods, and evidence based mobility development.', '高度なヨガシーケンス、深いストレッチ、逆転ポーズの準備、高度な呼吸法、瞑想、回復法、科学的根拠に基づく柔軟性向上を学びます。', 'Apply advanced yoga principles to maximise flexibility, balance, strength, mindfulness, and long term physical wellbeing.', '高度なヨガ理論を実践し、柔軟性、バランス、筋力、マインドフルネス、長期的な健康を最大限に高めます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(44, 11, 'Expert', '専門', 'Achieve expert level knowledge in yoga practice by integrating advanced movement science, breathing mastery, meditation techniques, and holistic wellness principles.', '高度な身体運動学、呼吸法、瞑想、総合的な健康理論を統合し、ヨガの専門知識を習得します。', 'Master advanced yoga programming, posture analysis, breathing techniques, meditation guidance, mobility assessment, recovery optimisation, teaching methodologies, and evidence based wellness practices.', '高度なヨガプログラム、姿勢分析、呼吸法、瞑想指導、柔軟性評価、回復最適化、指導法、科学的根拠に基づく健康促進法を総合的に学びます。', 'Demonstrate professional expertise in designing and guiding yoga programs that improve flexibility, mindfulness, physical health, and long term wellbeing.', '柔軟性、マインドフルネス、身体の健康、長期的な幸福を高めるヨガプログラムを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(45, 12, 'Beginner', '初級', 'Build a strong foundation in power yoga by learning dynamic yoga sequences, breathing techniques, posture alignment, and functional movement patterns. Improve strength, flexibility, endurance, and body awareness through structured practice.', 'ダイナミックなヨガシーケンス、呼吸法、正しい姿勢、機能的な動きを学び、パワーヨガの基礎を築きます。体系的な練習を通して筋力、柔軟性、持久力、身体意識を向上させます。', 'Learn beginner friendly power yoga poses, flowing transitions, breathing coordination, core activation, balance training, flexibility exercises, and recovery techniques. Understand how power yoga improves overall fitness, posture, and mobility.', '初心者向けのパワーヨガポーズ、流れるような動き、呼吸との連動、体幹強化、バランストレーニング、柔軟性向上、回復方法を学びます。パワーヨガが体力、姿勢、可動域を向上させる仕組みを理解します。', 'Develop the confidence to perform beginner power yoga routines safely while improving strength, flexibility, balance, and overall fitness.', '初心者向けパワーヨガを安全に実践し、筋力、柔軟性、バランス、総合的な体力を向上させることができます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(46, 12, 'Intermediate', '中級', 'Advance your power yoga practice through longer sequences, improved balance, strength development, endurance training, and mindful movement techniques.', 'より長いシーケンス、バランス向上、筋力強化、持久力トレーニング、マインドフルな動きを学び、パワーヨガをさらに発展させます。', 'Learn intermediate power yoga flows, dynamic transitions, advanced standing postures, breathing control, flexibility progression, recovery strategies, and structured workout planning.', '中級パワーヨガフロー、ダイナミックな動き、高度な立位ポーズ、呼吸コントロール、柔軟性向上、回復戦略、体系的なトレーニング計画を学びます。', 'Develop the ability to perform challenging power yoga sessions that improve endurance, muscular strength, flexibility, and movement quality.', '持久力、筋力、柔軟性、身体の動きの質を向上させる高度なパワーヨガセッションを実践できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(47, 12, 'Advanced', '上級', 'Master advanced power yoga through challenging sequences, strength focused practice, mobility development, breath control, and performance enhancement techniques.', '高度なシーケンス、筋力重視の練習、可動域向上、呼吸法、パフォーマンス向上技術を通じて上級パワーヨガを習得します。', 'Explore advanced power yoga programming, arm balances, inversion preparation, mobility improvement, meditation techniques, recovery optimisation, and evidence based movement training.', '高度なパワーヨガプログラム、アームバランス、逆転ポーズの準備、可動域向上、瞑想法、回復最適化、科学的根拠に基づくトレーニングを学びます。', 'Apply advanced power yoga principles to maximise strength, flexibility, endurance, balance, and long term physical performance.', '高度なパワーヨガ理論を活用し、筋力、柔軟性、持久力、バランス、長期的な身体能力を最大限に高めます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(48, 12, 'Expert', '専門', 'Achieve expert level knowledge in power yoga by integrating advanced movement science, yoga programming, performance coaching, and holistic wellness principles.', '高度な身体運動学、ヨガプログラム設計、パフォーマンスコーチング、総合的な健康理論を統合し、パワーヨガの専門知識を習得します。', 'Master advanced power yoga instruction, movement analysis, breathing mastery, performance assessment, recovery optimisation, coaching methodologies, and evidence based yoga programming.', '高度なパワーヨガ指導法、動作分析、呼吸法、パフォーマンス評価、回復最適化、コーチング手法、科学的根拠に基づくヨガプログラム設計を総合的に学びます。', 'Demonstrate professional expertise in designing and leading advanced power yoga programs that improve strength, mobility, endurance, and long term wellbeing.', '筋力、可動域、持久力、長期的な健康を向上させる高度なパワーヨガプログラムを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(49, 13, 'Beginner', '初級', 'Build a strong foundation in mobility and flexibility by learning safe stretching techniques, joint mobility exercises, posture improvement, and movement fundamentals. Improve range of motion, reduce stiffness, and support long term physical health.', '安全なストレッチ、関節の可動域向上エクササイズ、姿勢改善、基本的な身体の動きを学び、モビリティと柔軟性の基礎を築きます。可動域を広げ、身体の硬さを軽減し、長期的な健康をサポートします。', 'Learn beginner friendly stretching routines, joint mobility exercises, posture correction, balance training, movement preparation, recovery techniques, and flexibility development. Understand how regular mobility training improves physical performance and injury prevention.', '初心者向けストレッチ、関節モビリティエクササイズ、姿勢矯正、バランストレーニング、運動前の準備、回復法、柔軟性向上を学びます。継続的なモビリティトレーニングが身体能力向上と怪我予防につながる仕組みを理解します。', 'Develop the confidence to perform mobility and flexibility exercises safely while improving movement quality, posture, and overall physical wellbeing.', 'モビリティと柔軟性のエクササイズを安全に実践し、身体の動き、姿勢、健康全般を向上させることができます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(50, 13, 'Intermediate', '中級', 'Advance your mobility and flexibility through structured stretching routines, dynamic mobility drills, balance development, movement control, and recovery strategies.', '体系的なストレッチ、ダイナミックモビリティ、バランス向上、身体のコントロール、回復戦略を学び、モビリティと柔軟性をさらに高めます。', 'Learn intermediate flexibility training, dynamic stretching, joint stability exercises, movement assessment, mobility progression, recovery optimisation, and functional movement techniques.', '中級レベルの柔軟性トレーニング、ダイナミックストレッチ、関節安定化エクササイズ、動作評価、モビリティ向上、回復最適化、機能的な身体の動きを学びます。', 'Develop the ability to improve movement efficiency, flexibility, posture, and physical performance through structured mobility training.', '体系的なモビリティトレーニングを通じて、身体の動き、柔軟性、姿勢、身体能力を向上させることができます。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(51, 13, 'Advanced', '上級', 'Master advanced mobility and flexibility techniques through functional movement training, advanced stretching methods, joint health optimisation, and performance focused mobility development.', '機能的な身体の動き、高度なストレッチ、関節機能の最適化、パフォーマンス向上を目的としたモビリティトレーニングを通じて上級レベルを習得します。', 'Explore advanced mobility programming, movement analysis, corrective exercise techniques, flexibility progression, recovery planning, injury prevention, and evidence based mobility development strategies.', '高度なモビリティプログラム、動作分析、矯正エクササイズ、柔軟性向上、回復計画、怪我予防、科学的根拠に基づくモビリティ向上戦略を学びます。', 'Apply advanced mobility principles to maximise flexibility, movement quality, joint function, physical performance, and long term health.', '高度なモビリティ理論を活用し、柔軟性、身体の動き、関節機能、身体能力、長期的な健康を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(52, 13, 'Expert', '専門', 'Achieve expert level knowledge in mobility and flexibility by integrating movement science, corrective exercise, recovery optimisation, and professional mobility programming.', '身体運動学、矯正エクササイズ、回復最適化、専門的なモビリティプログラム設計を統合し、モビリティと柔軟性の専門知識を習得します。', 'Master advanced mobility assessment, flexibility programming, movement correction, joint health management, recovery strategies, coaching methodologies, and evidence based mobility training systems.', '高度なモビリティ評価、柔軟性プログラム設計、動作矯正、関節機能管理、回復戦略、コーチング手法、科学的根拠に基づくモビリティトレーニングシステムを総合的に学びます。', 'Demonstrate professional expertise in designing and implementing mobility and flexibility programs that improve movement quality, physical performance, injury prevention, and lifelong health.', '身体の動き、身体能力、怪我予防、生涯にわたる健康を向上させるモビリティと柔軟性プログラムを専門的に設計・実施できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(53, 14, 'Beginner', '初級', 'Start your day with energising yoga routines that improve flexibility, posture, circulation, and mental focus. Learn gentle morning movements that prepare your body and mind for a productive and healthy day.', '柔軟性、姿勢、血行、集中力を高める朝のヨガルーティンを学びます。穏やかな朝の動きを通じて、健康的で充実した一日を始めるための身体と心を整えます。', 'Learn beginner friendly morning yoga sequences, breathing exercises, gentle stretching, posture improvement, mobility training, relaxation techniques, and healthy daily movement habits. Understand how morning yoga supports energy, flexibility, stress reduction, and overall wellbeing.', '初心者向けの朝ヨガシーケンス、呼吸法、軽いストレッチ、姿勢改善、モビリティトレーニング、リラクゼーション、健康的な日常習慣を学びます。朝ヨガが活力、柔軟性、ストレス軽減、健康全般に役立つ仕組みを理解します。', 'Develop the confidence to practice safe and effective morning yoga routines that improve physical mobility, mental clarity, and daily wellbeing.', '安全で効果的な朝ヨガを実践し、身体の可動域、心の集中力、日々の健康を向上させることができます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(54, 14, 'Intermediate', '中級', 'Enhance your morning yoga practice through structured flows, breathing control, flexibility training, balance development, and mindful movement techniques.', '体系的なヨガフロー、呼吸コントロール、柔軟性向上、バランス強化、マインドフルな動きを学び、朝ヨガをさらに発展させます。', 'Learn intermediate morning yoga flows, dynamic stretching, mobility exercises, breathing coordination, balance improvement, recovery strategies, and movement awareness to maximise daily performance.', '中級レベルの朝ヨガフロー、ダイナミックストレッチ、モビリティエクササイズ、呼吸との連動、バランス向上、回復法、身体意識を学び、一日の身体能力を高めます。', 'Develop the ability to perform structured morning yoga sessions that improve flexibility, mobility, balance, and long term physical health.', '柔軟性、可動域、バランス、長期的な健康を向上させる朝ヨガセッションを実践できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(55, 14, 'Advanced', '上級', 'Master advanced morning yoga techniques through challenging sequences, mobility development, breath control, meditation, and performance focused practice.', '高度なヨガシーケンス、可動域向上、呼吸法、瞑想、身体能力向上を目的とした練習を通じて上級朝ヨガを習得します。', 'Explore advanced morning yoga programming, deep stretching, movement optimisation, mindfulness practices, recovery planning, flexibility progression, and evidence based mobility development.', '高度な朝ヨガプログラム、深いストレッチ、動作最適化、マインドフルネス、回復計画、柔軟性向上、科学的根拠に基づくモビリティ向上を学びます。', 'Apply advanced morning yoga principles to maximise flexibility, movement quality, mindfulness, physical performance, and daily wellness.', '高度な朝ヨガ理論を活用し、柔軟性、身体の動き、マインドフルネス、身体能力、日々の健康を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(56, 14, 'Expert', '専門', 'Achieve expert level knowledge in morning yoga by integrating movement science, breathing mastery, mindfulness practices, and holistic wellness strategies.', '身体運動学、呼吸法、マインドフルネス、総合的な健康戦略を統合し、朝ヨガの専門知識を習得します。', 'Master advanced morning yoga programming, posture analysis, breathing techniques, mobility assessment, recovery optimisation, coaching methodologies, and evidence based wellness practices.', '高度な朝ヨガプログラム、姿勢分析、呼吸法、モビリティ評価、回復最適化、コーチング手法、科学的根拠に基づく健康促進法を総合的に学びます。', 'Demonstrate professional expertise in designing and leading morning yoga programs that improve mobility, flexibility, mindfulness, and long term wellbeing.', '可動域、柔軟性、マインドフルネス、長期的な健康を向上させる朝ヨガプログラムを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(57, 15, 'Beginner', '初級', 'Discover how yoga can reduce stress, calm the mind, and improve overall wellbeing through gentle movement, breathing exercises, and relaxation techniques. Build healthy habits that support emotional balance and daily wellness.', '穏やかな動き、呼吸法、リラクゼーションを通じて、ストレスを軽減し、心を落ち着かせ、健康全般を向上させるヨガを学びます。心身のバランスと日々の健康を支える習慣を身につけます。', 'Learn beginner friendly stress relief yoga poses, breathing exercises, mindfulness techniques, gentle stretching, relaxation methods, posture improvement, and recovery practices. Understand how regular yoga supports mental clarity, flexibility, emotional wellbeing, and stress management.', '初心者向けのストレス解消ヨガ、呼吸法、マインドフルネス、軽いストレッチ、リラクゼーション、姿勢改善、回復法を学びます。継続的なヨガが心の安定、柔軟性、精神的健康、ストレス管理に役立つ仕組みを理解します。', 'Develop the confidence to practice stress relief yoga safely while improving relaxation, flexibility, mindfulness, and overall wellbeing.', 'ストレス解消ヨガを安全に実践し、リラクゼーション、柔軟性、マインドフルネス、健康全般を向上させることができます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(58, 15, 'Intermediate', '中級', 'Strengthen your stress management skills through structured yoga sequences, breathing control, mindfulness practices, flexibility development, and relaxation techniques.', '体系的なヨガシーケンス、呼吸コントロール、マインドフルネス、柔軟性向上、リラクゼーションを学び、ストレス管理能力をさらに高めます。', 'Learn intermediate stress relief yoga flows, breathing coordination, deep stretching, guided relaxation, meditation techniques, recovery practices, and movement awareness for improved mental and physical balance.', '中級レベルのストレス解消ヨガフロー、呼吸との連動、深いストレッチ、ガイド付きリラクゼーション、瞑想法、回復法、身体意識を学び、心身のバランスを高めます。', 'Develop the ability to perform structured yoga sessions that reduce stress, improve flexibility, promote relaxation, and enhance emotional wellbeing.', 'ストレスを軽減し、柔軟性を高め、心身をリラックスさせ、精神的健康を向上させるヨガセッションを実践できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(59, 15, 'Advanced', '上級', 'Master advanced stress relief yoga techniques through mindful movement, breath mastery, meditation, flexibility development, and holistic wellness practices.', 'マインドフルな動き、呼吸法、瞑想、柔軟性向上、総合的な健康法を通じて高度なストレス解消ヨガを習得します。', 'Explore advanced stress relief yoga programming, meditation practices, breathing mastery, movement optimisation, recovery strategies, emotional wellbeing techniques, and evidence based relaxation methods.', '高度なストレス解消ヨガプログラム、瞑想法、呼吸法、身体の動きの最適化、回復戦略、精神的健康向上、科学的根拠に基づくリラクゼーション技術を学びます。', 'Apply advanced yoga principles to maximise relaxation, mindfulness, flexibility, emotional resilience, and long term wellbeing.', '高度なヨガ理論を活用し、リラクゼーション、マインドフルネス、柔軟性、精神的な強さ、長期的な健康を最大限に高めます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(60, 15, 'Expert', '専門', 'Achieve expert level knowledge in stress relief yoga by integrating movement science, meditation, breathing mastery, mindfulness, and holistic wellness coaching.', '身体運動学、瞑想、呼吸法、マインドフルネス、総合的な健康指導を統合し、ストレス解消ヨガの専門知識を習得します。', 'Master advanced stress relief yoga instruction, emotional wellbeing strategies, breathing techniques, meditation guidance, recovery optimisation, coaching methodologies, and evidence based wellness practices.', '高度なストレス解消ヨガ指導法、精神的健康戦略、呼吸法、瞑想指導、回復最適化、コーチング手法、科学的根拠に基づく健康促進法を総合的に学びます。', 'Demonstrate professional expertise in designing and leading stress relief yoga programs that improve emotional wellbeing, relaxation, flexibility, mindfulness, and lifelong health.', '精神的健康、リラクゼーション、柔軟性、マインドフルネス、生涯にわたる健康を向上させるストレス解消ヨガプログラムを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(61, 16, 'Beginner', '初級', 'Build a strong foundation in sports nutrition by learning the role of carbohydrates, proteins, fats, hydration, vitamins, and minerals in supporting physical performance and recovery. Develop healthy eating habits that improve energy levels and overall fitness.', '炭水化物、たんぱく質、脂質、水分補給、ビタミン、ミネラルが運動能力や回復に果たす役割を学び、スポーツ栄養学の基礎を築きます。エネルギー向上と健康維持につながる食習慣を身につけます。', 'Learn the fundamentals of sports nutrition including macronutrients, micronutrients, hydration, meal timing, healthy food choices, recovery nutrition, and balanced eating habits. Understand how proper nutrition supports exercise performance, muscle recovery, and overall wellbeing.', '主要栄養素、微量栄養素、水分補給、食事のタイミング、健康的な食品の選び方、回復栄養、バランスの取れた食事など、スポーツ栄養学の基礎を学びます。適切な栄養が運動能力、筋肉の回復、健康全般を支える仕組みを理解します。', 'Develop the confidence to make healthy nutrition choices that improve physical performance, recovery, energy levels, and long term wellbeing.', '身体能力、回復、エネルギー、長期的な健康を向上させるための適切な栄養選択ができるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(62, 16, 'Intermediate', '中級', 'Expand your sports nutrition knowledge through balanced meal planning, nutrient timing, hydration strategies, recovery nutrition, and performance focused eating habits.', 'バランスの取れた食事計画、栄養摂取のタイミング、水分補給戦略、回復栄養、パフォーマンス向上のための食習慣を学び、スポーツ栄養学をさらに深めます。', 'Learn intermediate sports nutrition principles including meal planning, calorie management, nutrient timing, hydration optimisation, recovery meals, body composition support, and healthy performance nutrition.', '食事計画、カロリー管理、栄養摂取のタイミング、水分補給の最適化、回復食、身体組成の改善、競技力向上のための栄養管理など、中級レベルのスポーツ栄養学を学びます。', 'Develop the ability to plan balanced nutrition strategies that improve training performance, recovery, muscle development, and overall health.', 'トレーニング成果、回復、筋肉の発達、健康全般を向上させるバランスの取れた栄養計画を作成できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(63, 16, 'Advanced', '上級', 'Master advanced sports nutrition strategies through performance nutrition planning, nutrient periodisation, recovery optimisation, body composition management, and evidence based dietary approaches.', 'パフォーマンス栄養計画、栄養摂取の周期化、回復最適化、身体組成管理、科学的根拠に基づく食事法を通じて高度なスポーツ栄養学を習得します。', 'Explore advanced sports nutrition programming, nutrient analysis, performance meal planning, hydration science, recovery optimisation, supplementation principles, and evidence based nutrition strategies.', '高度なスポーツ栄養プログラム、栄養分析、競技向け食事計画、水分補給科学、回復最適化、サプリメントの基本、科学的根拠に基づく栄養戦略を学びます。', 'Apply advanced sports nutrition principles to maximise athletic performance, muscle recovery, body composition, and long term health.', '高度なスポーツ栄養理論を活用し、競技能力、筋肉の回復、身体組成、長期的な健康を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(64, 16, 'Expert', '専門', 'Achieve expert level knowledge in sports nutrition by integrating nutritional science, performance planning, recovery management, dietary assessment, and professional nutrition coaching principles.', '栄養学、競技力向上計画、回復管理、食事評価、専門的な栄養指導を統合し、スポーツ栄養学の専門知識を習得します。', 'Master advanced sports nutrition assessment, meal programming, hydration management, recovery nutrition, performance evaluation, coaching methodologies, and evidence based nutrition planning for athletes and active individuals.', '高度なスポーツ栄養評価、食事プログラム設計、水分管理、回復栄養、競技能力評価、コーチング手法、アスリートや運動習慣のある人向けの科学的根拠に基づく栄養計画を総合的に学びます。', 'Demonstrate professional expertise in designing nutrition programs that optimise athletic performance, recovery, body composition, health, and long term physical development.', '競技能力、回復、身体組成、健康、長期的な身体づくりを最適化する栄養プログラムを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(65, 17, 'Beginner', '初級', 'Learn how to create balanced meal plans that support fitness goals through proper portion control, healthy food selection, hydration, and consistent eating habits. Build a strong nutritional foundation for long term health and physical performance.', '適切な食事量、健康的な食品選び、水分補給、規則正しい食習慣を学び、フィットネス目標を支えるバランスの取れた食事計画を作成します。長期的な健康と身体能力向上のための栄養基盤を築きます。', 'Learn the fundamentals of fitness meal planning including calorie awareness, macronutrient balance, meal preparation, healthy food choices, hydration, grocery planning, and portion management. Understand how structured meal planning supports muscle growth, fat loss, energy levels, and overall wellbeing.', 'カロリー管理、主要栄養素のバランス、食事の準備、健康的な食品選び、水分補給、買い物計画、食事量の管理など、フィットネス向け食事計画の基礎を学びます。体系的な食事計画が筋肉の成長、脂肪減少、エネルギー向上、健康全般を支える仕組みを理解します。', 'Develop the confidence to create healthy meal plans that improve nutrition, physical performance, recovery, and long term wellness.', '栄養、身体能力、回復、長期的な健康を向上させる食事計画を作成できるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(66, 17, 'Intermediate', '中級', 'Improve your meal planning skills through personalised nutrition strategies, balanced meal preparation, nutrient timing, recovery nutrition, and sustainable healthy eating habits.', '個人に合わせた栄養戦略、バランスの取れた食事作り、栄養摂取のタイミング、回復栄養、持続可能な健康的食習慣を学び、食事計画スキルを向上させます。', 'Learn intermediate meal planning techniques including calorie management, macronutrient distribution, weekly meal preparation, grocery organisation, hydration planning, and nutrition strategies for active lifestyles.', 'カロリー管理、主要栄養素の配分、週間食事準備、買い物管理、水分補給計画、活動的な生活に適した栄養戦略など、中級レベルの食事計画を学びます。', 'Develop the ability to design balanced meal plans that support muscle development, fat loss, recovery, performance, and healthy living.', '筋肉の発達、脂肪減少、回復、身体能力、健康的な生活を支えるバランスの取れた食事計画を作成できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(67, 17, 'Advanced', '上級', 'Master advanced meal planning strategies through nutrition periodisation, performance focused meal design, body composition management, and evidence based dietary planning.', '栄養摂取の周期化、競技向け食事設計、身体組成管理、科学的根拠に基づく食事計画を通じて高度な食事計画を習得します。', 'Explore advanced meal planning systems including performance nutrition, metabolic health, nutrient analysis, recovery meal optimisation, body composition planning, and evidence based dietary strategies.', '競技栄養、代謝管理、栄養分析、回復食の最適化、身体組成計画、科学的根拠に基づく食事戦略など、高度な食事計画システムを学びます。', 'Apply advanced nutrition planning principles to maximise physical performance, recovery, body composition, and lifelong healthy eating habits.', '高度な栄養計画を活用し、身体能力、回復、身体組成、生涯にわたる健康的な食習慣を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(68, 17, 'Expert', '専門', 'Achieve expert level knowledge in meal planning by integrating nutrition science, dietary assessment, performance nutrition, behaviour coaching, and professional meal planning methodologies.', '栄養学、食事評価、競技栄養、行動コーチング、専門的な食事計画手法を統合し、食事計画の専門知識を習得します。', 'Master advanced meal planning assessment, nutritional programming, dietary analysis, performance meal design, recovery nutrition, coaching methodologies, and evidence based nutrition systems for long term health and fitness.', '高度な食事計画評価、栄養プログラム設計、食事分析、競技向け食事設計、回復栄養、コーチング手法、長期的な健康とフィットネスのための科学的根拠に基づく栄養システムを総合的に学びます。', 'Demonstrate professional expertise in designing personalised meal plans that optimise performance, recovery, body composition, health, and sustainable nutrition habits.', '身体能力、回復、身体組成、健康、持続可能な食習慣を最適化する個別食事プランを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(69, 18, 'Beginner', '初級', 'Build a strong understanding of protein and muscle nutrition by learning how protein supports muscle growth, recovery, strength, and overall physical performance. Develop healthy eating habits that provide the nutrients needed for consistent training progress.', 'たんぱく質が筋肉の成長、回復、筋力、身体能力に果たす役割を学び、筋肉栄養学の基礎を築きます。継続的なトレーニングを支える健康的な食習慣を身につけます。', 'Learn the fundamentals of protein nutrition including protein sources, daily requirements, meal timing, amino acids, muscle recovery, balanced nutrition, and healthy eating strategies. Understand how protein supports muscle development, exercise recovery, and long term physical health.', 'たんぱく質の供給源、必要摂取量、食事のタイミング、アミノ酸、筋肉の回復、バランスの取れた栄養、健康的な食習慣など、たんぱく質栄養学の基礎を学びます。たんぱく質が筋肉の発達、運動後の回復、長期的な健康を支える仕組みを理解します。', 'Develop the confidence to choose appropriate protein sources and nutrition strategies that improve muscle recovery, strength, and overall fitness.', '筋肉の回復、筋力、総合的な体力を向上させるために適切なたんぱく質源と栄養戦略を選択できるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(70, 18, 'Intermediate', '中級', 'Expand your knowledge of muscle nutrition through protein planning, nutrient timing, recovery nutrition, balanced meal design, and performance focused eating strategies.', 'たんぱく質計画、栄養摂取のタイミング、回復栄養、バランスの取れた食事設計、競技力向上のための栄養戦略を学び、筋肉栄養学をさらに深めます。', 'Learn intermediate protein nutrition strategies including protein distribution, meal planning, recovery nutrition, muscle maintenance, calorie management, hydration, and performance nutrition for active lifestyles.', 'たんぱく質の配分、食事計画、回復栄養、筋肉維持、カロリー管理、水分補給、活動的な生活に適した栄養管理など、中級レベルの筋肉栄養学を学びます。', 'Develop the ability to create nutrition plans that support muscle growth, recovery, strength development, and long term physical performance.', '筋肉の成長、回復、筋力向上、長期的な身体能力を支える栄養計画を作成できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(71, 18, 'Advanced', '上級', 'Master advanced protein and muscle nutrition strategies through nutrient periodisation, performance nutrition, recovery optimisation, body composition management, and evidence based dietary planning.', '栄養摂取の周期化、競技栄養、回復最適化、身体組成管理、科学的根拠に基づく食事計画を通じて高度なたんぱく質栄養学を習得します。', 'Explore advanced protein nutrition programming including amino acid metabolism, performance meal planning, recovery optimisation, body composition analysis, supplementation principles, and evidence based nutrition strategies.', 'アミノ酸代謝、競技向け食事計画、回復最適化、身体組成分析、サプリメントの基本、科学的根拠に基づく栄養戦略など、高度なたんぱく質栄養学を学びます。', 'Apply advanced protein nutrition principles to maximise muscle growth, recovery, strength, body composition, and long term athletic performance.', '高度なたんぱく質栄養理論を活用し、筋肉の成長、回復、筋力、身体組成、長期的な身体能力を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(72, 18, 'Expert', '専門', 'Achieve expert level knowledge in protein and muscle nutrition by integrating nutritional science, performance planning, dietary assessment, recovery management, and professional nutrition coaching.', '栄養学、競技力向上計画、食事評価、回復管理、専門的な栄養指導を統合し、たんぱく質栄養学の専門知識を習得します。', 'Master advanced protein nutrition assessment, meal programming, dietary analysis, recovery nutrition, performance evaluation, coaching methodologies, and evidence based nutrition systems for muscle development and athletic performance.', '高度なたんぱく質栄養評価、食事プログラム設計、食事分析、回復栄養、競技能力評価、コーチング手法、筋肉の発達と競技力向上のための科学的根拠に基づく栄養システムを総合的に学びます。', 'Demonstrate professional expertise in designing nutrition programs that optimise muscle growth, recovery, body composition, strength, and long term physical performance.', '筋肉の成長、回復、身体組成、筋力、長期的な身体能力を最適化する栄養プログラムを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(73, 19, 'Beginner', '初級', 'Build a strong foundation in healthy weight management by learning balanced nutrition, portion control, healthy eating habits, hydration, and sustainable lifestyle practices. Develop the knowledge needed to achieve and maintain a healthy body weight safely and effectively.', 'バランスの取れた栄養、食事量の管理、健康的な食習慣、水分補給、持続可能な生活習慣を学び、健康的な体重管理の基礎を築きます。安全かつ効果的に適正体重を維持するための知識を身につけます。', 'Learn the fundamentals of healthy weight management including calorie awareness, balanced nutrition, portion control, meal planning, hydration, physical activity, and healthy lifestyle habits. Understand how sustainable nutrition and exercise contribute to long term weight management and overall wellbeing.', 'カロリー管理、バランスの取れた栄養、食事量の管理、食事計画、水分補給、身体活動、健康的な生活習慣など、健康的な体重管理の基礎を学びます。持続可能な栄養管理と運動が長期的な体重管理と健康全般にどのように役立つかを理解します。', 'Develop the confidence to manage body weight through healthy nutrition, regular physical activity, and sustainable lifestyle habits.', '健康的な栄養、定期的な運動、持続可能な生活習慣を通じて適正体重を維持できるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(74, 19, 'Intermediate', '中級', 'Expand your knowledge of healthy weight management through personalised nutrition planning, calorie management, meal preparation, behaviour change strategies, and long term healthy lifestyle development.', '個人に合わせた栄養計画、カロリー管理、食事準備、行動改善戦略、長期的な健康習慣を学び、体重管理スキルをさらに向上させます。', 'Learn intermediate weight management techniques including nutrition planning, calorie balance, meal timing, exercise support, hydration strategies, behaviour modification, and sustainable healthy living practices.', '栄養計画、カロリーバランス、食事のタイミング、運動サポート、水分補給戦略、行動改善、持続可能な健康習慣など、中級レベルの体重管理を学びます。', 'Develop the ability to create sustainable nutrition and lifestyle plans that support healthy body weight, physical fitness, and overall wellbeing.', '健康的な体重、身体能力、健康全般を支える持続可能な栄養と生活習慣の計画を作成できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(75, 19, 'Advanced', '上級', 'Master advanced healthy weight management strategies through nutrition periodisation, body composition analysis, metabolic health, behavioural coaching, and evidence based dietary planning.', '栄養摂取の周期化、身体組成分析、代謝管理、行動コーチング、科学的根拠に基づく食事計画を通じて高度な体重管理を習得します。', 'Explore advanced weight management systems including body composition assessment, metabolic nutrition, performance meal planning, behavioural psychology, recovery nutrition, and evidence based healthy lifestyle strategies.', '身体組成評価、代謝栄養学、競技向け食事計画、行動心理学、回復栄養、科学的根拠に基づく健康戦略など、高度な体重管理システムを学びます。', 'Apply advanced weight management principles to improve body composition, metabolic health, physical performance, and long term wellness.', '高度な体重管理理論を活用し、身体組成、代謝健康、身体能力、長期的な健康を向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(76, 19, 'Expert', '専門', 'Achieve expert level knowledge in healthy weight management by integrating nutrition science, behavioural coaching, body composition assessment, performance planning, and professional wellness strategies.', '栄養学、行動コーチング、身体組成評価、健康計画、専門的なウェルネス戦略を統合し、健康的な体重管理の専門知識を習得します。', 'Master advanced weight management assessment, nutrition programming, body composition analysis, healthy lifestyle coaching, behavioural change systems, and evidence based wellness planning for long term health improvement.', '高度な体重管理評価、栄養プログラム設計、身体組成分析、健康指導、行動改善システム、長期的な健康向上のための科学的根拠に基づくウェルネス計画を総合的に学びます。', 'Demonstrate professional expertise in designing personalised weight management programs that optimise body composition, health, physical performance, and sustainable lifestyle improvement.', '身体組成、健康、身体能力、持続可能な生活改善を最適化する体重管理プログラムを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(77, 20, 'Beginner', '初級', 'Build a strong foundation in sports nutrition by learning how balanced nutrition, hydration, meal timing, and healthy food choices support athletic performance, recovery, and overall physical wellbeing. Develop practical habits that improve energy levels and training consistency.', 'バランスの取れた栄養、水分補給、食事のタイミング、健康的な食品選びを学び、スポーツ栄養学の基礎を築きます。運動能力、回復、健康全般を支える実践的な食習慣を身につけます。', 'Learn the fundamentals of sports nutrition including energy balance, macronutrients, micronutrients, hydration, pre workout nutrition, post workout recovery, healthy meal planning, and nutritional support for active lifestyles. Understand how proper nutrition improves physical performance, endurance, recovery, and long term athletic development.', 'エネルギーバランス、主要栄養素、微量栄養素、水分補給、運動前後の栄養、健康的な食事計画、活動的な生活のための栄養管理など、スポーツ栄養学の基礎を学びます。適切な栄養が身体能力、持久力、回復、長期的な競技力向上にどのように役立つかを理解します。', 'Develop the confidence to apply healthy sports nutrition practices that improve athletic performance, recovery, energy levels, and overall health.', '競技力、回復、エネルギー、健康全般を向上させるスポーツ栄養の実践方法を身につけます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(78, 20, 'Intermediate', '中級', 'Expand your sports nutrition knowledge through personalised meal planning, nutrient timing, hydration strategies, recovery nutrition, and performance focused dietary planning.', '個人に合わせた食事計画、栄養摂取のタイミング、水分補給戦略、回復栄養、競技力向上のための食事計画を学び、スポーツ栄養学をさらに深めます。', 'Learn intermediate sports nutrition techniques including performance meal planning, hydration management, macronutrient distribution, recovery nutrition, energy balance, body composition support, and nutrition strategies for active individuals.', '競技向け食事計画、水分補給管理、主要栄養素の配分、回復栄養、エネルギーバランス、身体組成管理、活動的な人のための栄養戦略など、中級レベルのスポーツ栄養学を学びます。', 'Develop the ability to create nutrition plans that support athletic performance, recovery, endurance, strength, and overall physical wellbeing.', '競技力、回復、持久力、筋力、健康全般を支える栄養計画を作成できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(79, 20, 'Advanced', '上級', 'Master advanced sports nutrition strategies through performance nutrition, nutrient periodisation, body composition management, recovery optimisation, and evidence based dietary planning.', '競技栄養、栄養摂取の周期化、身体組成管理、回復最適化、科学的根拠に基づく食事計画を通じて高度なスポーツ栄養学を習得します。', 'Explore advanced sports nutrition systems including metabolic nutrition, nutrient timing, performance meal programming, supplementation principles, recovery optimisation, body composition analysis, and evidence based nutrition strategies.', '代謝栄養学、栄養摂取のタイミング、競技向け食事プログラム、サプリメントの基本、回復最適化、身体組成分析、科学的根拠に基づく栄養戦略など、高度なスポーツ栄養学を学びます。', 'Apply advanced sports nutrition principles to maximise athletic performance, endurance, recovery, body composition, and long term physical development.', '高度なスポーツ栄養理論を活用し、競技力、持久力、回復、身体組成、長期的な身体能力を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(80, 20, 'Expert', '専門', 'Achieve expert level knowledge in sports nutrition by integrating nutrition science, performance assessment, recovery planning, dietary programming, and professional athlete nutrition strategies.', '栄養学、競技評価、回復計画、食事プログラム設計、アスリート向け栄養戦略を統合し、スポーツ栄養学の専門知識を習得します。', 'Master advanced sports nutrition assessment, performance meal programming, dietary analysis, hydration planning, recovery nutrition, coaching methodologies, and evidence based nutrition systems for competitive athletes and fitness professionals.', '高度なスポーツ栄養評価、競技向け食事プログラム設計、食事分析、水分補給計画、回復栄養、コーチング手法、競技者やフィットネス指導者向けの科学的根拠に基づく栄養システムを総合的に学びます。', 'Demonstrate professional expertise in designing personalised sports nutrition programs that optimise athletic performance, recovery, body composition, endurance, and long term health.', '競技力、回復、身体組成、持久力、長期的な健康を最適化するスポーツ栄養プログラムを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(81, 21, 'Beginner', '初級', 'Build a strong foundation for becoming a certified personal trainer by learning exercise fundamentals, client safety, professional ethics, communication skills, and basic fitness coaching principles. Develop the confidence needed to begin guiding clients toward their health and fitness goals.', '運動の基礎、クライアントの安全管理、職業倫理、コミュニケーション能力、基本的なフィットネス指導を学び、認定パーソナルトレーナーとしての基礎を築きます。クライアントの健康とフィットネス目標を支援する自信を身につけます。', 'Learn the fundamentals of personal training including exercise instruction, client communication, health screening, movement assessment, basic program design, safety guidelines, and professional responsibilities. Understand the essential knowledge required to begin a successful career in personal training.', '運動指導、クライアントとのコミュニケーション、健康チェック、動作評価、基本的なプログラム設計、安全ガイドライン、職業上の責任など、パーソナルトレーニングの基礎を学びます。パーソナルトレーナーとして成功するために必要な知識を理解します。', 'Develop the confidence to assist clients safely while building the knowledge required for personal trainer certification and professional fitness coaching.', '安全にクライアントを指導し、認定パーソナルトレーナーとして必要な知識と指導力を身につけます。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(82, 21, 'Intermediate', '中級', 'Expand your personal training knowledge through exercise programming, client assessment, motivational coaching, injury prevention, and effective communication techniques for diverse fitness goals.', '運動プログラム設計、クライアント評価、モチベーション指導、怪我の予防、多様な目標に対応するコミュニケーション技術を学び、パーソナルトレーナーとしての知識を深めます。', 'Learn intermediate personal training techniques including exercise selection, programme progression, client monitoring, fitness assessment, coaching psychology, movement correction, and professional client management.', '運動種目の選択、プログラムの進行管理、クライアントのモニタリング、体力評価、コーチング心理学、動作修正、クライアント管理など、中級レベルのパーソナルトレーニング技術を学びます。', 'Develop the ability to create structured fitness programmes while improving coaching effectiveness, client satisfaction, and exercise safety.', '安全で効果的なフィットネスプログラムを設計し、指導力とクライアント満足度を向上させます。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(83, 21, 'Advanced', '上級', 'Master advanced personal training concepts through programme periodisation, advanced client assessment, corrective exercise principles, performance coaching, and evidence based fitness programming.', 'プログラムの周期化、高度なクライアント評価、修正運動、競技力向上指導、科学的根拠に基づくプログラム設計を通じて高度なパーソナルトレーニングを習得します。', 'Explore advanced personal training systems including movement analysis, programme periodisation, performance assessment, corrective exercise strategies, recovery planning, coaching leadership, and evidence based fitness methodologies.', '動作分析、プログラムの周期化、競技能力評価、修正運動戦略、回復計画、リーダーシップ、科学的根拠に基づくフィットネス指導法など、高度なパーソナルトレーニングを学びます。', 'Apply advanced coaching principles to improve client performance, movement quality, injury prevention, and long term fitness success.', '高度な指導技術を活用し、クライアントの競技力、動作品質、怪我予防、長期的な成功を支援します。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(84, 21, 'Expert', '専門', 'Achieve expert level knowledge in personal training by integrating exercise science, advanced coaching, client management, business practices, and professional certification preparation.', '運動科学、高度なコーチング、クライアント管理、ビジネス知識、資格試験対策を統合し、パーソナルトレーナーとしての専門知識を習得します。', 'Master advanced personal trainer assessment, programme design, coaching systems, performance evaluation, corrective exercise programming, client relationship management, and evidence based professional fitness coaching methodologies.', '高度なクライアント評価、プログラム設計、コーチングシステム、パフォーマンス評価、修正運動プログラム、顧客管理、科学的根拠に基づく専門的フィットネス指導法を総合的に学びます。', 'Demonstrate professional expertise in delivering safe, effective, and personalised fitness coaching while preparing for certified personal trainer level responsibilities.', '認定パーソナルトレーナーとして安全で効果的かつ個別化された指導を提供できる専門能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(85, 22, 'Beginner', '初級', 'Build a strong foundation in exercise science by learning human anatomy, physiology, biomechanics, movement principles, and the basic science behind physical activity. Develop the knowledge required to understand how the body responds to exercise safely and effectively.', '人体解剖学、生理学、バイオメカニクス、動作原理、運動の基礎科学を学び、運動科学の基礎を築きます。身体が運動にどのように反応するかを安全かつ効果的に理解するための知識を身につけます。', 'Learn the fundamentals of exercise science including anatomy, physiology, biomechanics, energy systems, muscular function, cardiovascular health, and movement mechanics. Understand how scientific principles support safe exercise, physical performance, injury prevention, and long term fitness development.', '解剖学、生理学、バイオメカニクス、エネルギーシステム、筋機能、心血管の健康、動作力学など、運動科学の基礎を学びます。科学的原則が安全な運動、身体能力、怪我の予防、長期的なフィットネス向上をどのように支えるかを理解します。', 'Develop the confidence to understand exercise science principles that support safe training, improved performance, and lifelong physical health.', '安全なトレーニング、身体能力の向上、生涯にわたる健康を支える運動科学の原則を理解できるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(86, 22, 'Intermediate', '中級', 'Expand your exercise science knowledge through advanced anatomy, movement analysis, exercise physiology, biomechanics, and evidence based training principles.', '高度な解剖学、動作分析、運動生理学、バイオメカニクス、科学的根拠に基づくトレーニング原則を学び、運動科学の理解を深めます。', 'Learn intermediate exercise science concepts including muscular adaptations, cardiovascular responses, movement efficiency, flexibility, recovery physiology, exercise prescription, and scientific training methods.', '筋適応、心血管反応、動作効率、柔軟性、回復生理学、運動処方、科学的トレーニング方法など、中級レベルの運動科学を学びます。', 'Develop the ability to apply exercise science principles to improve movement quality, training effectiveness, recovery, and physical performance.', '運動科学の知識を活用し、動作品質、トレーニング効果、回復、身体能力を向上させることができます。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(87, 22, 'Advanced', '上級', 'Master advanced exercise science through biomechanics, exercise physiology, movement assessment, performance analysis, recovery science, and evidence based programming.', 'バイオメカニクス、運動生理学、動作評価、パフォーマンス分析、回復科学、科学的根拠に基づくプログラム設計を通じて高度な運動科学を習得します。', 'Explore advanced exercise science systems including neuromuscular function, metabolic adaptations, movement screening, performance optimisation, injury prevention, recovery planning, and scientific training methodologies.', '神経筋機能、代謝適応、動作スクリーニング、競技力向上、怪我予防、回復計画、科学的トレーニング手法など、高度な運動科学を学びます。', 'Apply advanced exercise science principles to maximise movement efficiency, physical performance, injury prevention, and long term athletic development.', '高度な運動科学を活用し、動作効率、身体能力、怪我予防、長期的な競技力向上を実現します。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(88, 22, 'Expert', '専門', 'Achieve expert level knowledge in exercise science by integrating anatomy, physiology, biomechanics, movement analysis, research interpretation, and professional coaching methodologies.', '解剖学、生理学、バイオメカニクス、動作分析、研究解析、専門的な指導法を統合し、運動科学の専門知識を習得します。', 'Master advanced exercise science assessment, performance analysis, movement evaluation, physiological monitoring, scientific programme design, coaching systems, and evidence based fitness methodologies for professional practice.', '高度な運動科学評価、パフォーマンス分析、動作評価、生理学的モニタリング、科学的プログラム設計、コーチングシステム、科学的根拠に基づくフィットネス指導法を総合的に学びます。', 'Demonstrate professional expertise in applying exercise science to optimise physical performance, movement quality, client safety, and long term health outcomes.', '運動科学を活用して身体能力、動作品質、安全性、長期的な健康成果を最適化できる専門能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(89, 23, 'Beginner', '初級', 'Build a strong foundation in client assessment and exercise programming by learning health screening, fitness evaluations, goal setting, and basic programme design. Develop the skills needed to create safe and effective training plans for clients with different fitness levels.', '健康チェック、体力評価、目標設定、基本的なプログラム設計を学び、クライアント評価と運動プログラム作成の基礎を築きます。さまざまな体力レベルのクライアントに安全で効果的なトレーニング計画を作成するスキルを身につけます。', 'Learn the fundamentals of client assessment including health screening, posture evaluation, movement analysis, fitness testing, goal setting, programme planning, and exercise selection. Understand how personalised exercise programmes improve safety, performance, motivation, and long term fitness success.', '健康チェック、姿勢評価、動作分析、体力測定、目標設定、プログラム計画、運動種目の選択など、クライアント評価の基礎を学びます。個別の運動プログラムが安全性、身体能力、モチベーション、長期的なフィットネス成果をどのように向上させるかを理解します。', 'Develop the confidence to assess clients and create personalised fitness programmes that support safe and effective progress.', 'クライアントを適切に評価し、安全で効果的な個別フィットネスプログラムを作成できるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(90, 23, 'Intermediate', '中級', 'Expand your client assessment and programming skills through movement screening, fitness testing, programme progression, exercise modification, and performance monitoring.', '動作スクリーニング、体力測定、プログラムの進行管理、運動の修正、パフォーマンス管理を学び、クライアント評価とプログラム設計をさらに深めます。', 'Learn intermediate client assessment techniques including movement analysis, exercise progression, programme customisation, strength evaluation, flexibility assessment, recovery planning, and performance tracking.', '動作分析、運動の進行管理、プログラムの個別化、筋力評価、柔軟性評価、回復計画、パフォーマンス追跡など、中級レベルのクライアント評価とプログラム設計を学びます。', 'Develop the ability to design personalised training programmes that improve fitness, movement quality, performance, and client satisfaction.', '身体能力、動作品質、競技力、クライアント満足度を向上させる個別トレーニングプログラムを設計できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(91, 23, 'Advanced', '上級', 'Master advanced client assessment and programming through performance analysis, corrective exercise, programme periodisation, movement optimisation, and evidence based coaching methods.', 'パフォーマンス分析、修正運動、プログラムの周期化、動作最適化、科学的根拠に基づく指導法を通じて高度なクライアント評価とプログラム設計を習得します。', 'Explore advanced client assessment systems including functional movement screening, performance testing, programme periodisation, injury prevention strategies, corrective exercise programming, recovery planning, and evidence based coaching methodologies.', '機能的動作評価、パフォーマンス測定、プログラムの周期化、怪我予防、修正運動プログラム、回復計画、科学的根拠に基づくコーチング手法など、高度なクライアント評価システムを学びます。', 'Apply advanced assessment and programming principles to maximise client performance, safety, movement quality, and long term fitness success.', '高度な評価とプログラム設計を活用し、クライアントの身体能力、安全性、動作品質、長期的な成果を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(92, 23, 'Expert', '専門', 'Achieve expert level knowledge in client assessment and programming by integrating movement science, exercise prescription, performance evaluation, coaching systems, and professional programme design.', '動作科学、運動処方、パフォーマンス評価、コーチングシステム、専門的なプログラム設計を統合し、クライアント評価とプログラム設計の専門知識を習得します。', 'Master advanced client assessment, programme development, movement evaluation, performance monitoring, corrective exercise planning, coaching methodologies, and evidence based fitness programming for professional practice.', '高度なクライアント評価、プログラム開発、動作評価、パフォーマンス管理、修正運動計画、コーチング手法、専門的な実践のための科学的根拠に基づくフィットネスプログラム設計を総合的に学びます。', 'Demonstrate professional expertise in assessing clients and designing highly personalised fitness programmes that optimise performance, safety, health, and long term success.', '身体能力、安全性、健康、長期的な成果を最適化する高度に個別化されたフィットネスプログラムを専門的に設計・指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(93, 24, 'Beginner', '初級', 'Build a strong foundation in group fitness coaching by learning class leadership, exercise instruction, participant safety, communication skills, and motivational coaching techniques. Develop the confidence to lead enjoyable and effective group fitness sessions.', 'クラス運営、運動指導、参加者の安全管理、コミュニケーション能力、モチベーション指導を学び、グループフィットネスコーチングの基礎を築きます。楽しく効果的なグループレッスンを指導する自信を身につけます。', 'Learn the fundamentals of group fitness coaching including class planning, exercise demonstration, cueing techniques, participant engagement, safety procedures, music coordination, and effective communication. Understand how to create motivating group fitness experiences that improve health, fitness, and enjoyment.', 'クラス計画、運動デモンストレーション、指示方法、参加者とのコミュニケーション、安全管理、音楽の活用、効果的な指導方法など、グループフィットネスコーチングの基礎を学びます。健康、体力、楽しさを高める魅力的なグループレッスンの作り方を理解します。', 'Develop the confidence to lead safe, engaging, and motivating group fitness classes for participants of different fitness levels.', 'さまざまな体力レベルの参加者に対して、安全で魅力的かつ意欲を高めるグループレッスンを指導できるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(94, 24, 'Intermediate', '中級', 'Expand your group fitness coaching skills through class programming, participant management, exercise progression, coaching communication, and motivational leadership techniques.', 'クラスプログラム設計、参加者管理、運動の進行管理、指導コミュニケーション、モチベーションリーダーシップを学び、グループフィットネス指導力を向上させます。', 'Learn intermediate group fitness coaching techniques including class structure, participant assessment, exercise modification, coaching psychology, energy management, group motivation, and performance monitoring.', 'クラス構成、参加者評価、運動の修正、コーチング心理学、エネルギー管理、グループのモチベーション向上、パフォーマンス管理など、中級レベルのグループフィットネス指導法を学びます。', 'Develop the ability to deliver structured group fitness programmes that improve participation, performance, motivation, and overall class experience.', '参加率、身体能力、モチベーション、クラス全体の満足度を高めるグループプログラムを実施できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(95, 24, 'Advanced', '上級', 'Master advanced group fitness coaching through programme periodisation, advanced coaching methods, class performance analysis, participant engagement strategies, and evidence based instruction.', 'プログラムの周期化、高度な指導法、クラス分析、参加者エンゲージメント、科学的根拠に基づく指導法を通じて高度なグループフィットネスコーチングを習得します。', 'Explore advanced group fitness coaching systems including class periodisation, participant performance evaluation, leadership development, exercise progression, motivational psychology, recovery planning, and evidence based coaching methodologies.', 'クラスの周期化、参加者のパフォーマンス評価、リーダーシップ育成、運動の進行管理、モチベーション心理学、回復計画、科学的根拠に基づく指導法など、高度なグループフィットネスシステムを学びます。', 'Apply advanced coaching principles to maximise class engagement, participant performance, exercise safety, and long term fitness success.', '高度な指導技術を活用し、参加者の満足度、身体能力、安全性、長期的な成果を最大限に向上させます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(96, 24, 'Expert', '専門', 'Achieve expert level knowledge in group fitness coaching by integrating leadership, exercise science, programme design, participant management, and professional coaching methodologies.', 'リーダーシップ、運動科学、プログラム設計、参加者管理、専門的な指導法を統合し、グループフィットネスコーチングの専門知識を習得します。', 'Master advanced group fitness programme development, participant assessment, leadership strategies, performance evaluation, coaching systems, class management, and evidence based instruction for professional group fitness coaching.', '高度なグループフィットネスプログラム開発、参加者評価、リーダーシップ戦略、パフォーマンス評価、コーチングシステム、クラス運営、科学的根拠に基づく指導法を総合的に学びます。', 'Demonstrate professional expertise in leading engaging group fitness programmes that maximise participant safety, motivation, performance, and long term health outcomes.', '参加者の安全性、モチベーション、身体能力、長期的な健康成果を最大限に高めるグループフィットネスプログラムを専門的に指導できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL),
(97, 25, 'Beginner', '初級', 'Build a strong foundation in online fitness coaching by learning virtual client communication, online programme delivery, digital coaching tools, goal setting, and client support strategies. Develop the confidence to coach clients effectively through online platforms.', 'オンラインでのクライアントとのコミュニケーション、オンラインプログラム提供、デジタルコーチングツール、目標設定、クライアントサポートを学び、オンラインフィットネスコーチングの基礎を築きます。オンライン環境で効果的に指導する自信を身につけます。', 'Learn the fundamentals of online fitness coaching including virtual consultations, exercise programming, client communication, progress tracking, digital coaching platforms, motivation techniques, and online business best practices. Understand how to deliver safe, engaging, and effective coaching experiences remotely.', 'オンライン相談、運動プログラム設計、クライアントとのコミュニケーション、進捗管理、デジタルコーチングツール、モチベーション向上法、オンラインビジネスの基本など、オンラインフィットネスコーチングの基礎を学びます。安全で魅力的かつ効果的なオンライン指導を提供する方法を理解します。', 'Develop the confidence to coach clients online while delivering personalised programmes, effective communication, and ongoing support.', '個別プログラム、効果的なコミュニケーション、継続的なサポートを提供しながら、オンラインでクライアントを指導できるようになります。', 19.00, 19.00, 19.00, 19, NULL, NULL),
(98, 25, 'Intermediate', '中級', 'Expand your online coaching skills through digital programme design, client engagement strategies, progress monitoring, behaviour coaching, and online business management.', 'デジタルプログラム設計、クライアントエンゲージメント、進捗管理、行動コーチング、オンラインビジネス運営を学び、オンラインコーチングスキルを向上させます。', 'Learn intermediate online coaching techniques including personalised programme development, virtual assessments, online accountability systems, client retention strategies, digital communication, performance monitoring, and coaching psychology.', '個別プログラム開発、オンライン評価、継続サポートシステム、顧客維持戦略、デジタルコミュニケーション、パフォーマンス管理、コーチング心理学など、中級レベルのオンラインコーチングを学びます。', 'Develop the ability to build successful online coaching programmes that improve client engagement, consistency, results, and satisfaction.', 'クライアントの継続率、成果、満足度を高めるオンラインコーチングプログラムを構築できるようになります。', 29.00, 29.00, 29.00, 29, NULL, NULL),
(99, 25, 'Advanced', '上級', 'Master advanced online fitness coaching through scalable coaching systems, business growth strategies, advanced programme design, performance analysis, and evidence based coaching methods.', '拡張可能なコーチングシステム、ビジネス成長戦略、高度なプログラム設計、パフォーマンス分析、科学的根拠に基づく指導法を通じて高度なオンラインフィットネスコーチングを習得します。', 'Explore advanced online coaching systems including digital client management, programme automation, performance analytics, behaviour change strategies, business scaling, leadership development, and evidence based coaching methodologies.', 'デジタル顧客管理、プログラム自動化、パフォーマンス分析、行動改善戦略、ビジネス拡大、リーダーシップ育成、科学的根拠に基づく指導法など、高度なオンラインコーチングシステムを学びます。', 'Apply advanced online coaching principles to maximise client success, business growth, programme quality, and long term coaching effectiveness.', '高度なオンラインコーチング技術を活用し、クライアントの成果、事業成長、プログラム品質、長期的な指導効果を最大限に高めます。', 39.00, 39.00, 39.00, 39, NULL, NULL),
(100, 25, 'Expert', '専門', 'Achieve expert level knowledge in online fitness coaching by integrating digital coaching technologies, business systems, exercise science, client management, and professional coaching methodologies.', 'デジタルコーチング技術、ビジネスシステム、運動科学、クライアント管理、専門的なコーチング手法を統合し、オンラインフィットネスコーチングの専門知識を習得します。', 'Master advanced online coaching programme development, digital client assessment, business management, coaching systems, leadership strategies, performance evaluation, and evidence based online fitness coaching methodologies for professional practice.', '高度なオンラインコーチングプログラム開発、デジタルクライアント評価、ビジネス管理、コーチングシステム、リーダーシップ戦略、パフォーマンス評価、専門的実践のための科学的根拠に基づくオンラインフィットネス指導法を総合的に学びます。', 'Demonstrate professional expertise in delivering scalable, personalised, and results driven online fitness coaching programmes that maximise client success, engagement, and long term health outcomes.', 'クライアントの成果、継続率、長期的な健康成果を最大化する、拡張性があり個別化された成果重視のオンラインフィットネスコーチングを専門的に提供できる能力を習得します。', 49.00, 49.00, 49.00, 49, NULL, NULL);
